/* ---------- generic non-indexed geometry merger ---------- */
/* items: {geo, color, x,y,z, rx,ry,rz, sx,sy,sz} — consumes geo */
const _mm=new THREE.Matrix4(),_me=new THREE.Euler();
function mergeGeoms(items){
  const pos=[],nor=[],col=[];
  for(const it of items){
    let g=it.geo.index?it.geo.toNonIndexed():it.geo;
    _me.set(it.rx||0,it.ry||0,it.rz||0);
    _mm.makeRotationFromEuler(_me);
    _mm.setPosition(it.x||0,it.y||0,it.z||0);
    if(it.sx||it.sy||it.sz)g.scale(it.sx||1,it.sy||1,it.sz||1);
    g.applyMatrix4(_mm);
    const p=g.attributes.position.array,n=g.attributes.normal.array;
    const c=new THREE.Color(it.color);
    for(let i=0;i<p.length;i++){pos.push(p[i]);nor.push(n[i]);}
    for(let i=0;i<p.length/3;i++)col.push(c.r,c.g,c.b);
    g.dispose();if(g!==it.geo)it.geo.dispose();}
  const out=new THREE.BufferGeometry();
  out.setAttribute("position",new THREE.Float32BufferAttribute(pos,3));
  out.setAttribute("normal",new THREE.Float32BufferAttribute(nor,3));
  out.setAttribute("color",new THREE.Float32BufferAttribute(col,3));
  return out;
}

/* ---------- body loft: 8-point cross-section stations ---------- */
/* station fields (normalized: w,x in hx / y in hy / z in hz):
   z, w(lower width), y0(floor), y1(belt), y2(roof), wt(roof width),
   glass(side glass segment), top(roof segment is glass e.g. windshield) */
function carStations(spec){
  const{hx,hy,hz}=spec.body,st=spec.style;
  const S=(z,w,y0,y1,y2,wt,glass,top)=>({z:z*hz,w:w*hx,y0:y0*hy,y1:y1*hy,y2:y2*hy,
    wt:(wt??.64)*hx,glass:glass||0,top:top||0});
  if(st==="hatch")return[
    S(1,.72,-.62,-.08,-.02,.58),S(.92,.92,-.78,.02,.1,.72),S(.62,1,-.85,.1,.18,.8),
    S(.38,1,-.86,.14,.24,.82),S(.14,1,-.86,.14,.9,.66,0,1),S(.02,.995,-.86,.14,.96,.64),
    S(-.3,1,-.86,.14,1,.64,1),S(-.62,.99,-.85,.12,.97,.63,1),S(-.8,.96,-.8,.1,.9,.62,1,1),
    S(-.92,.9,-.72,.05,.4,.6),S(-1,.74,-.6,-.05,.28,.56)];
  if(st==="coupe")return[
    S(1,.74,-.68,-.24,-.16,.6),S(.9,.94,-.85,-.12,-.02,.76),S(.55,1,-.9,-.02,.1,.84),
    S(.28,1,-.9,.02,.16,.84),S(.1,1,-.9,.04,.76,.62,0,1),S(-.02,.995,-.9,.05,.84,.58),
    S(-.35,1,-.9,.05,.86,.58,1),S(-.58,.99,-.88,.04,.72,.56,1,1),
    S(-.8,.97,-.82,.02,.3,.66),S(-1,.78,-.65,-.1,.16,.62)];
  if(st==="suv")return[
    S(1,.8,-.5,0,.1,.66),S(.9,.96,-.68,.12,.3,.8),S(.66,1,-.75,.18,.4,.84),
    S(.46,1,-.78,.2,.42,.84),S(.3,1,-.78,.2,1,.76,0,1),S(.18,.995,-.78,.2,1.05,.74),
    S(-.2,1,-.78,.2,1.06,.74,1),S(-.6,1,-.78,.2,1.05,.74,1),S(-.88,.98,-.74,.17,1,.72,1),
    S(-1,.8,-.55,.05,.92,.68)];
  if(st==="truck")return[
    S(1,.78,-.42,.12,.32,.66),S(.96,.95,-.5,.3,.55,.8),S(.88,.96,-.55,.32,.9,.78,0,1),
    S(.72,.96,-.6,.32,.95,.78,1),S(.54,.94,-.62,.3,.9,.76),
    S(.48,.99,-.65,.4,1.02,.92),S(-.9,.99,-.65,.4,1.02,.92),S(-1,.92,-.55,.3,.97,.86)];
  /* super */ return[
    S(1,.7,-.8,-.56,-.5,.58),S(.85,.95,-.95,-.42,-.32,.8),S(.5,1,-1,-.3,-.16,.86),
    S(.27,1,-1,-.26,-.1,.86),S(.1,1,-1,-.24,.48,.6,0,1),S(-.02,.995,-1,-.22,.62,.56),
    S(-.3,1,-1,-.2,.66,.56,1),S(-.48,1,-1,-.18,.52,.6,1,1),
    S(-.72,.99,-.95,-.15,.32,.74),S(-1,.84,-.75,-.3,.2,.7)];
}
const GLASS_COL=new THREE.Color(0x151d28);
function buildCarBody(spec,colorHex){
  const st=carStations(spec);
  const body=new THREE.Color(colorHex);
  const shade=body.clone().multiplyScalar(.66);
  const dark=body.clone().multiplyScalar(.42);
  const roof=body.clone().multiplyScalar(.88);
  const pos=[],col=[];
  // 8 section points: 0 bl,1 br,2 rockerR,3 beltR,4 roofR,5 roofL,6 beltL,7 rockerL
  const P=(s,k)=>{
    const wf=s.w*1.04,yf=s.y0+(s.y1-s.y0)*.3,wb=s.w*.985;
    switch(k){case 0:return[-s.w*.92,s.y0];case 1:return[s.w*.92,s.y0];
      case 2:return[wf,yf];case 3:return[wb,s.y1];case 4:return[s.wt,s.y2];
      case 5:return[-s.wt,s.y2];case 6:return[-wb,s.y1];default:return[-wf,yf];}};
  const quad=(p1,p2,p3,p4,za,zb,c)=>{
    pos.push(p1[0],p1[1],za, p4[0],p4[1],zb, p3[0],p3[1],zb,
             p1[0],p1[1],za, p3[0],p3[1],zb, p2[0],p2[1],za);
    for(let i=0;i<6;i++)col.push(c.r,c.g,c.b);};
  for(let i=0;i<st.length-1;i++){
    const a=st[i],b=st[i+1];
    const sideGlass=(a.glass||b.glass)?GLASS_COL:body;
    const topC=(a.top||b.top)?GLASS_COL:roof;
    const edges=[[0,1,dark],[1,2,shade],[2,3,body],[3,4,sideGlass],[4,5,topC],
                 [5,6,sideGlass],[6,7,body],[7,0,shade]];
    for(const[k1,k2,c]of edges)
      quad(P(a,k1),P(a,k2),P(b,k2),P(b,k1),a.z,b.z,c);}
  // caps (front & rear faces) as fans
  const cap=(s,rev,c)=>{
    for(let k=1;k<7;k++){
      const[x0,y0]=P(s,0),[x1,y1]=P(s,k),[x2,y2]=P(s,k+1);
      if(rev)pos.push(x0,y0,s.z,x1,y1,s.z,x2,y2,s.z);
      else pos.push(x0,y0,s.z,x2,y2,s.z,x1,y1,s.z);
      for(let i=0;i<3;i++)col.push(c.r,c.g,c.b);}};
  cap(st[0],false,body);cap(st[st.length-1],true,shade);
  // fake AO: darken toward floor
  let yMin=1e9,yMax=-1e9;
  for(let i=1;i<pos.length;i+=3){yMin=Math.min(yMin,pos[i]);yMax=Math.max(yMax,pos[i]);}
  for(let i=0;i<pos.length;i+=3){
    const t=.72+.28*clamp((pos[i+1]-yMin)/(yMax-yMin+1e-6),0,1);
    col[i]*=t;col[i+1]*=t;col[i+2]*=t;}
  const g=new THREE.BufferGeometry();
  g.setAttribute("position",new THREE.Float32BufferAttribute(pos,3));
  g.setAttribute("color",new THREE.Float32BufferAttribute(col,3));
  g.computeVertexNormals();
  return g;
}
/* interpolate station roof height / belt at z (for part placement) */
function stationLerp(st,z,key){
  for(let i=0;i<st.length-1;i++){
    const a=st[i],b=st[i+1];
    if((z<=a.z&&z>=b.z)||(z>=a.z&&z<=b.z)){
      const t=(z-a.z)/((b.z-a.z)||1e-6);return lerp(a[key],b[key],t);}}
  return st[0][key];
}

const MAT_CAR=new THREE.MeshPhongMaterial({vertexColors:true,flatShading:true,shininess:70,specular:0x555555});
const MAT_DETAIL=new THREE.MeshPhongMaterial({vertexColors:true,flatShading:true,shininess:30,specular:0x222222});
let _wheelGeoCache={};
function wheelGeo(r,wd){ // merged tire+rim+spokes, vertex colors
  const k=(r*100|0)+"_"+(wd*100|0);
  if(!_wheelGeoCache[k]){
    const items=[
      {geo:new THREE.CylinderGeometry(r,r,wd,16),color:0x16181c,rz:Math.PI/2},
      {geo:new THREE.CylinderGeometry(r*.58,r*.58,wd+.015,10),color:0xb8bfc9,rz:Math.PI/2},
      {geo:new THREE.CylinderGeometry(r*.16,r*.16,wd+.05,8),color:0x30343c,rz:Math.PI/2}];
    for(let s=0;s<5;s++)items.push({geo:new THREE.BoxGeometry(wd+.03,r*.42,r*.16),
      color:0x585f6a,rx:s*Math.PI*2/5,y:0,z:0});
    // spokes rotate around x-axis: build them along y then rotate about x
    _wheelGeoCache[k]=mergeGeoms(items.map((it,i)=>{
      if(i>=3){const a=(i-3)*Math.PI*2/5;
        return{geo:new THREE.BoxGeometry(wd+.02,r*.9,r*.14),color:0x9aa2ad,rx:a};}
      return it;}));}
  return _wheelGeoCache[k];
}

/* deform helper (unchanged API) */
function deformGeo(mesh,lp,ln,d,R,cap){
  const g=mesh.geometry,posA=g.attributes.position;
  if(!posA)return 0;
  if(!mesh.userData.orig)mesh.userData.orig=posA.array.slice();
  const arr=posA.array,off=mesh.position;
  const lx=lp.x-off.x,ly=lp.y-off.y,lz=lp.z-off.z;
  let moved=false,vol=0;
  for(let i=0;i<arr.length;i+=3){
    const dx=arr[i]-lx,dy=arr[i+1]-ly,dz=arr[i+2]-lz;
    const dist=Math.sqrt(dx*dx+dy*dy+dz*dz);
    if(dist<R){
      const t=1-(dist/R)*(dist/R),f=t*t*d;
      let nx=arr[i]+ln.x*f,ny=arr[i+1]+ln.y*f,nz=arr[i+2]+ln.z*f;
      const o=mesh.userData.orig;
      const tx=nx-o[i],ty=ny-o[i+1],tz=nz-o[i+2];
      const tot=Math.sqrt(tx*tx+ty*ty+tz*tz);
      if(tot>cap){const s=cap/tot;nx=o[i]+tx*s;ny=o[i+1]+ty*s;nz=o[i+2]+tz*s;}
      arr[i]=nx;arr[i+1]=ny;arr[i+2]=nz;moved=true;vol+=f;}}
  if(moved){posA.needsUpdate=true;g.computeVertexNormals();}
  return vol;
}
function restoreGeo(mesh){
  if(!mesh.userData.orig)return;
  mesh.geometry.attributes.position.array.set(mesh.userData.orig);
  mesh.geometry.attributes.position.needsUpdate=true;
  mesh.geometry.computeVertexNormals();
}

/* ---------- car visual ---------- */
class CarVisual{
  constructor(spec,colorHex){
    this.spec=spec;
    this.group=new THREE.Group();
    this.baked=(typeof BAKED!=="undefined")&&BAKED[spec.model]||null;
    if(this.baked)this.buildBaked(spec,colorHex);
    else this.buildProcedural(spec,colorHex);
    this.hp0=Object.assign({},this.partHp);
    this.detached={};
    this.defVol=0;
  }
  mkPart(w,h,d,x,y,z,mat){
    const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d,2,1,2).toNonIndexed(),mat);
    m.position.set(x,y,z);m.castShadow=true;this.group.add(m);return m;}

  /* ===== 외부(베이크) 모델 차량 ===== */
  buildBaked(spec,colorHex){
    const e=this.baked,{hx,hy,hz}=spec.body;
    this.bodyMesh=new THREE.Mesh(Assets.geo(e,{scale:spec.modelScale,
      cx:spec.modelCx,cy:spec.modelCy,cz:spec.modelCz,paint:new THREE.Color(colorHex)}),MAT_CAR);
    this.bodyMesh.castShadow=true;this.group.add(this.bodyMesh);
    const bumpMat=new THREE.MeshPhongMaterial({color:0x191d24,flatShading:true,shininess:18});
    const by=Math.max(spec.modelWheelY,-hy*.62);
    this.parts={
      fb:this.mkPart(hx*1.15,hy*.16,.1,0,by,hz-.01,bumpMat),
      rb:this.mkPart(hx*1.15,hy*.16,.1,0,by,-hz+.01,bumpMat),
      ml:this.mkPart(.07,.08,.17,-hx*.92,hy*.1,hz*.3,bumpMat),
      mr:this.mkPart(.07,.08,.17,hx*.92,hy*.1,hz*.3,bumpMat)};
    this.partHp={fb:1.3,rb:1.3,ml:.3,mr:.3};
    if(!e.wheel._geos)e.wheel._geos={};
    const wg=e.wheel._geos[spec.id]||(e.wheel._geos[spec.id]=
      Assets.geo(e.wheel,{scale:spec.modelScale}));
    this.wheelMeshes=[];
    for(let i=0;i<4;i++){
      const m=new THREE.Mesh(wg,MAT_DETAIL);m.castShadow=true;
      const grp=new THREE.Group();grp.add(m);
      this.group.add(grp);this.wheelMeshes.push(grp);}
  }

  /* ===== 절차 생성 차량 (폴백) ===== */
  buildProcedural(spec,colorHex){
    const{hx,hy,hz}=spec.body,st=carStations(spec),W=spec.wheels;
    const bodyC=new THREE.Color(colorHex);
    const shadeC=bodyC.clone().multiplyScalar(.72);
    this.bodyMesh=new THREE.Mesh(buildCarBody(spec,colorHex),MAT_CAR);
    this.bodyMesh.castShadow=true;
    this.group.add(this.bodyMesh);
    const det=[];
    const wellR=W.radius+.1;
    for(const[wx,wz]of[[-W.track,W.front],[W.track,W.front],[-W.track,-W.rear],[W.track,-W.rear]])
      det.push({geo:new THREE.CylinderGeometry(wellR,wellR,W.width+.14,10,1,true,0,Math.PI),
        color:0x0c0e12,x:wx,y:W.y+.02,z:wz,rz:Math.PI/2});
    const noseY=stationLerp(st,hz*.97,"y1"),tailY=stationLerp(st,-hz*.97,"y1");
    det.push({geo:new THREE.BoxGeometry(hx*.9,hy*.18,.05),color:0x10141a,x:0,y:noseY*.65-hy*.18,z:hz-.02});
    det.push({geo:new THREE.BoxGeometry(.34,.12,.03),color:0xe8ecf2,x:0,y:-hy*.5,z:hz+.09});
    det.push({geo:new THREE.BoxGeometry(.34,.12,.03),color:0xe8ecf2,x:0,y:-hy*.5,z:-hz-.09});
    for(const ex of spec.style==="super"?[-.3,-.1,.1,.3]:[-.25,.25])
      det.push({geo:new THREE.CylinderGeometry(.045,.045,.14,7),color:0x2e343c,
        x:ex*hx,y:-hy*.72,z:-hz-.04,rx:Math.PI/2});
    const beltY=stationLerp(st,0,"y1");
    for(const s2 of[-1,1])det.push({geo:new THREE.BoxGeometry(.03,.03,.16),color:0x1c2026,
      x:s2*hx*1.0,y:beltY-.05,z:hz*.06});
    this.detailMesh=new THREE.Mesh(mergeGeoms(det),MAT_DETAIL);
    this.detailMesh.castShadow=true;
    this.group.add(this.detailMesh);
    const li=[];
    const hlY=spec.style==="super"?-hy*.45:noseY*.4;
    for(const s2 of[-1,1]){
      li.push({geo:new THREE.BoxGeometry(hx*.44,.1,.05),color:0xfff6d8,x:s2*hx*.56,y:hlY,z:hz+.01});
      li.push({geo:new THREE.BoxGeometry(hx*.4,.09,.05),color:0xff2a2a,x:s2*hx*.56,y:tailY*.5,z:-hz-.01});}
    this.lightsMesh=new THREE.Mesh(mergeGeoms(li),new THREE.MeshBasicMaterial({vertexColors:true}));
    this.group.add(this.lightsMesh);
    const partMat=new THREE.MeshPhongMaterial({color:bodyC.clone().multiplyScalar(.92),flatShading:true,shininess:55});
    const bumpMat=new THREE.MeshPhongMaterial({color:0x191d24,flatShading:true,shininess:18});
    const mirrMat=new THREE.MeshPhongMaterial({color:bodyC.clone().multiplyScalar(.8),flatShading:true,shininess:55});
    const hoodY=stationLerp(st,hz*.5,"y2");
    this.parts={
      fb:this.mkPart(hx*1.78,hy*.3,.18,0,-hy*.6,hz+.05,bumpMat),
      rb:this.mkPart(hx*1.78,hy*.3,.18,0,-hy*.6,-hz-.05,bumpMat),
      dl:this.mkPart(.05,hy*.66,hz*.56,-hx-.02,-hy*.2,hz*.04,partMat),
      dr:this.mkPart(.05,hy*.66,hz*.56,hx+.02,-hy*.2,hz*.04,partMat),
      ml:this.mkPart(.07,.09,.2,-hx-.1,stationLerp(st,hz*.12,"y1")+.14,hz*.14,mirrMat),
      mr:this.mkPart(.07,.09,.2,hx+.1,stationLerp(st,hz*.12,"y1")+.14,hz*.14,mirrMat),
      hood:this.mkPart(hx*1.5,.05,hz*.42,0,hoodY+.02,hz*.6,partMat),
      trunk:this.mkPart(hx*1.35,hy*.55,.05,0,stationLerp(st,-hz*.99,"y1")+hy*.28,-hz-.02,partMat)};
    this.partHp={fb:1,rb:1,hood:1,trunk:1,dl:1,dr:1,ml:.35,mr:.35};
    this.wheelMeshes=[];
    const wg=wheelGeo(W.radius,W.width);
    for(let i=0;i<4;i++){
      const m=new THREE.Mesh(wg,MAT_DETAIL);
      const grp=new THREE.Group();grp.add(m);
      this.group.add(grp);this.wheelMeshes.push(grp);}
  }
  applyImpact(imp,veh){
    const dv=imp.dv;
    const d=Math.min(.4,.015*dv),R=.5+.02*dv;
    this.defVol+=deformGeo(this.bodyMesh,imp.lp,imp.ln,d,R,.45);
    if(this.detailMesh)deformGeo(this.detailMesh,imp.lp,imp.ln,d*.8,R,.4);
    for(const k in this.parts){
      const p=this.parts[k];
      if(this.detached[k])continue;
      deformGeo(p,imp.lp,imp.ln,d,R,.4);
      _vA.copy(imp.lp).sub(p.position);
      if(_vA.length()<R+.5){
        this.partHp[k]-=dv*.02*(k==="fb"||k==="rb"?1.6:(k==="ml"||k==="mr")?3:1);
        if(this.partHp[k]<=0&&veh.damageOn)this.detachPart(k,veh,imp);}}
  }
  detachPart(k,veh,imp){
    if(this.detached[k])return;
    const p=this.parts[k];this.detached[k]=p;
    Fx.addDebris(p,veh,imp);
  }
  repair(){
    restoreGeo(this.bodyMesh);
    if(this.detailMesh)restoreGeo(this.detailMesh);
    this.defVol=0;
    for(const k in this.parts){
      const p=this.parts[k];restoreGeo(p);this.partHp[k]=this.hp0[k];
      if(this.detached[k]){Fx.reclaimDebris(p);this.group.add(p);
        p.material.opacity=1;p.material.transparent=false;
        p.position.copy(p.userData.home);p.quaternion.identity();
        delete this.detached[k];}}
  }
  storeHomes(){for(const k in this.parts)this.parts[k].userData.home=this.parts[k].position.clone();}
  sync(veh,shakeT){
    this.group.position.copy(veh.body.pos);
    this.group.quaternion.copy(veh.body.quat);
    if(shakeT>0&&Settings.camShake){
      this.group.position.x+=(Math.random()-.5)*.02;this.group.position.y+=(Math.random()-.5)*.02;}
    const tv=this.baked?this.spec.wheels.trackVis:0;
    for(let i=0;i<4;i++){
      const w=veh.wheels[i],m=this.wheelMeshes[i];
      m.position.set(this.baked?(w.left?-tv:tv):w.local.x,w.visY,w.local.z);
      const st=(w.front?veh.steer:0)+(w.left?-veh.toe:veh.toe)*8;
      m.rotation.set(0,st,0);
      m.children[0].rotation.x=w.spin;}
  }
  dispose(){
    this.group.parent&&this.group.parent.remove(this.group);
    this.bodyMesh.geometry.dispose();
    if(this.detailMesh)this.detailMesh.geometry.dispose();
    if(this.lightsMesh)this.lightsMesh.geometry.dispose();
    for(const k in this.parts)this.parts[k].geometry.dispose();
  }
}
/* ============================================================
   Maps — heightfield terrain + static OBB structures + props
   ============================================================ */
const SURF_ID={};SURF_IDS.forEach((k,i)=>SURF_ID[k]=i);

class MapBuilder{
  constructor(size,res){
    this.world=new World(size,res);
    this.group=new THREE.Group();
    this.mergePos=[];this.mergeNor=[];this.mergeCol=[];
    this.props=[];this.laneDots=[];
  }
  fill(fn){ // fn(x,z) -> [height, surfId]
    const w=this.world,r=w.res;
    for(let j=0;j<=r;j++)for(let i=0;i<=r;i++){
      const x=i*w.cell-w.size*.5,z=j*w.cell-w.size*.5;
      const[h,s]=fn(x,z);
      w.setH(i,j,h);w.setS(i,j,s);}
  }
  stamp(x,z,rad,cb){ // cb(i,j,dist,x,z)
    const w=this.world,c=w.cell,half=w.size*.5;
    const i0=Math.max(0,Math.floor((x-rad+half)/c)),i1=Math.min(w.res,Math.ceil((x+rad+half)/c));
    const j0=Math.max(0,Math.floor((z-rad+half)/c)),j1=Math.min(w.res,Math.ceil((z+rad+half)/c));
    for(let j=j0;j<=j1;j++)for(let i=i0;i<=i1;i++){
      const px=i*c-half,pz=j*c-half;
      const d=Math.hypot(px-x,pz-z);
      if(d<=rad)cb(i,j,d,px,pz);}
  }
  paintPath(pts,width,surfId,flatten,lane){ // pts: [{x,y,z}]  y used when flatten
    const w=this.world,step=w.cell*.5;
    let dist=0;
    for(let k=0;k<pts.length-1;k++){
      const a=pts[k],b=pts[k+1];
      const len=Math.hypot(b.x-a.x,b.z-a.z),n=Math.max(1,Math.ceil(len/step));
      for(let s=0;s<=n;s++){
        const t=s/n,x=lerp(a.x,b.x,t),z=lerp(a.z,b.z,t),y=lerp(a.y,b.y,t);
        this.stamp(x,z,width*.5+(flatten?w.cell*1.6:0),(i,j,d)=>{
          const idx=w.idx(i,j);
          if(flatten){
            const f=clamp((d-width*.5)/(w.cell*1.6),0,1);
            w.hMap[idx]=lerp(y,w.hMap[idx],f*f);}
          if(d<=width*.5)w.sMap[idx]=surfId;});
        dist+=len/n;
        if(lane&&(dist%9)<4)this.laneDots.push([x,z]);}}
  }
  paintLanes(){ // 차선은 도로 도색이 모두 끝난 뒤 덧칠
    const w=this.world;
    for(const[x,z]of this.laneDots)
      this.stamp(x,z,w.cell*.55,(i,j)=>{
        if(w.sMap[w.idx(i,j)]===SURF_ID.asphalt)w.sMap[w.idx(i,j)]=SURF_ID.lane;});
    this.laneDots.length=0;}
  baked(name,x,z,scale,yaw,opt){ // 베이크 배경 모델 배치 (+선택 OBB)
    opt=opt||{};
    if(typeof BAKED==="undefined"||!BAKED[name])return;
    const e=BAKED[name],A=Assets.arrays(e);
    const y=opt.y!==undefined?opt.y:this.world.height(x,z);
    const ca=Math.cos(yaw||0),sa=Math.sin(yaw||0);
    for(let i=0;i<A.n;i++){
      const px=A.pos[i*3]*scale,py=A.pos[i*3+1]*scale,pz=A.pos[i*3+2]*scale;
      this.mergePos.push(px*ca+pz*sa+x,py+y,-px*sa+pz*ca+z);
      const nx=A.nor[i*3],nz=A.nor[i*3+2];
      this.mergeNor.push(nx*ca+nz*sa,A.nor[i*3+1],-nx*sa+nz*ca);
      this.mergeCol.push(A.col[i*3],A.col[i*3+1],A.col[i*3+2]);}
    if(opt.collide){
      const bb=e.bb;
      const hw=(bb[3]-bb[0])/2*scale*(opt.shrink||1),hh=(bb[4]-bb[1])/2*scale,hd=(bb[5]-bb[2])/2*scale*(opt.shrink||1);
      this.world.boxes.push(new OBB(x,y+hh,z,hw,hh,hd,yaw||0,0,0,{mu:.5,tag:name}));}
  }
  box(x,y,z,w,h,d,color,opt){ // opt:{yaw,pitch,roll,mu,bounce,tag,noVis}
    opt=opt||{};
    const obb=new OBB(x,y,z,w/2,h/2,d/2,opt.yaw||0,opt.pitch||0,opt.roll||0,opt);
    this.world.boxes.push(obb);
    if(!opt.noVis)this.visBox(x,y,z,w,h,d,color,opt);
    return obb;}
  visBox(x,y,z,w,h,d,color,opt){
    opt=opt||{};
    const g=new THREE.BoxGeometry(w,h,d).toNonIndexed();
    g.applyMatrix4(new THREE.Matrix4().makeRotationFromEuler(new THREE.Euler(opt.pitch||0,opt.yaw||0,opt.roll||0,"YXZ")));
    g.translate(x,y,z);
    const p=g.attributes.position.array,nr=g.attributes.normal.array;
    const c=new THREE.Color(color);
    for(let i=0;i<p.length;i++){this.mergePos.push(p[i]);this.mergeNor.push(nr[i]);}
    for(let i=0;i<p.length/3;i++)this.mergeCol.push(c.r,c.g,c.b);
    g.dispose();}
  bump(x,z,yaw,width){ // 과속방지턱: 9cm 낮은 사다리꼴(OBB) + 노랑/검정 표시
    const y=this.world.height(x,z);
    this.box(x,y+.045,z,width,.09,.85,0xe8b93c,{yaw,mu:1,tag:"bump"});
    // black stripes (visual only)
    const n=Math.max(2,Math.round(width/1.6));
    for(let i=0;i<n;i++){
      const t=(i+.5)/n-.5;
      this.visBox(x+Math.cos(yaw)*t*width,y+.095,z-Math.sin(yaw)*t*width,
        width/n*.5,.012,.86,0x23262c,{yaw});}
    return this;}
  ramp(x,z,yaw,pitchDeg,len,wid,color){ // ramp whose surface rises along +local z
    const pitch=-pitchDeg*DEG,h=.5;
    const rise=Math.sin(-pitch)*len;
    const cy=this.world.height(x,z)+rise*.5- h*.35;
    return this.box(x,cy,z,wid,h,len,color||0x8f98a3,{yaw,pitch,mu:1,tag:"ramp"});}
  prop(type,x,z,yaw){
    const w=this.world,y=w.height(x,z);
    const p=makeProp(type,x,y,z,yaw||0);
    w.props.push(p);this.group.add(p.mesh);return p;}
  finalize(mapDef){
    const w=this.world;
    // ground mesh
    const res=Math.min(w.res,192);
    const g=new THREE.PlaneGeometry(w.size,w.size,res,res);
    g.rotateX(-Math.PI/2);
    const pos=g.attributes.position,cols=new Float32Array(pos.count*3);
    const cTmp=new THREE.Color();
    for(let vi=0;vi<pos.count;vi++){
      const x=pos.getX(vi),z=pos.getZ(vi);
      pos.setY(vi,w.height(x,z));
      const s=w.surf(x,z);
      cTmp.set(SURF[SURF_IDS[s]].col);
      const n=.94+.06*Math.sin(x*12.9898+z*78.233);
      cols[vi*3]=cTmp.r*n;cols[vi*3+1]=cTmp.g*n;cols[vi*3+2]=cTmp.b*n;}
    g.setAttribute("color",new THREE.BufferAttribute(cols,3));
    g.computeVertexNormals();
    const ground=new THREE.Mesh(g,new THREE.MeshLambertMaterial({vertexColors:true}));
    ground.receiveShadow=true;
    this.group.add(ground);
    // merged static boxes
    if(this.mergePos.length){
      const mg=new THREE.BufferGeometry();
      mg.setAttribute("position",new THREE.Float32BufferAttribute(this.mergePos,3));
      mg.setAttribute("normal",new THREE.Float32BufferAttribute(this.mergeNor,3));
      mg.setAttribute("color",new THREE.Float32BufferAttribute(this.mergeCol,3));
      const mm=new THREE.Mesh(mg,new THREE.MeshLambertMaterial({vertexColors:true}));
      mm.castShadow=true;mm.receiveShadow=true;
      this.group.add(mm);}
    this.mergePos=this.mergeNor=this.mergeCol=null;
    w.mapDef=mapDef;
    return{world:w,group:this.group};}
}

/* path helpers */
function samplePath(ctrl,closed,n){
  const v=ctrl.map(p=>V3(p[0],p[2]!==undefined?p[2]:0,p[1]));
  const curve=new THREE.CatmullRomCurve3(v.map(p=>V3(p.x,p.y,p.z)),closed,"catmullrom",.5);
  const pts=[];
  for(let i=0;i<=n;i++){const p=curve.getPoint(i/n);pts.push({x:p.x,y:p.y,z:p.z});}
  return pts;}
function pathWaypoints(pts,closed,vmax){
  const wp=[];
  const N=pts.length-1;
  for(let i=0;i<N;i+=2){
    const a=pts[(i-2+N)%N],b=pts[i],c=pts[(i+2)%N];
    const v1x=b.x-a.x,v1z=b.z-a.z,v2x=c.x-b.x,v2z=c.z-b.z;
    const l1=Math.hypot(v1x,v1z)||1,l2=Math.hypot(v2x,v2z)||1;
    const cos=clamp((v1x*v2x+v1z*v2z)/(l1*l2),-1,1);
    const ang=Math.acos(cos),curvature=ang/((l1+l2)*.5+1e-3);
    const v=clamp(Math.sqrt(7.5/Math.max(curvature,1e-4)),9,vmax||55);
    wp.push({x:b.x,z:b.z,v});}
  // smooth speeds backward (braking anticipation)
  for(let k=0;k<3;k++)for(let i=wp.length-1;i>=0;i--){
    const nx=wp[(i+1)%wp.length];wp[i].v=Math.min(wp[i].v,nx.v+4.5);}
  return wp;}
function pathCheckpoints(pts,every,rad){
  const cp=[];
  for(let i=0;i<pts.length-1;i+=every)cp.push({x:pts[i].x,z:pts[i].z,r:rad||14});
  return cp;}
function railAlong(mb,pts,width,color,skip){ // guardrails both sides
  for(let i=0;i<pts.length-2;i+=2){
    const a=pts[i],b=pts[i+2];
    const dx=b.x-a.x,dz=b.z-a.z,len=Math.hypot(dx,dz);
    if(len<1)continue;
    const yaw=Math.atan2(dx,dz),nx=dz/len,nz=-dx/len;
    for(const s of[-1,1]){
      if(skip&&skip(a,s))continue;
      const px=(a.x+b.x)/2+nx*s*(width/2+.6),pz=(a.z+b.z)/2+nz*s*(width/2+.6);
      const y=mb.world.height(px,pz);
      mb.box(px,y+.45,pz,.25,.7,len+.4,color||0xb9c2cc,{yaw,mu:.4,bounce:.25,tag:"rail"});}}
}

/* ---------- props ---------- */
const PROP_DEFS={
  cone:{r:.28,m:4,mk(){const g=new THREE.Group();
    const c=new THREE.Mesh(new THREE.ConeGeometry(.22,.55,8),new THREE.MeshLambertMaterial({color:0xff7518}));
    c.position.y=.28;g.add(c);
    const b=new THREE.Mesh(new THREE.BoxGeometry(.4,.05,.4),new THREE.MeshLambertMaterial({color:0xd85f10}));
    b.position.y=.025;g.add(b);return g;}},
  sign:{r:.35,m:14,mk(){const g=new THREE.Group();
    const p=new THREE.Mesh(new THREE.CylinderGeometry(.04,.04,2.1,6),new THREE.MeshLambertMaterial({color:0x8a94a0}));
    p.position.y=1.05;g.add(p);
    const s=new THREE.Mesh(new THREE.BoxGeometry(.62,.62,.04),new THREE.MeshLambertMaterial({color:0x2477ff}));
    s.position.y=1.9;g.add(s);return g;}},
  lamp:{r:.4,m:38,mk(){const g=new THREE.Group();
    const p=new THREE.Mesh(new THREE.CylinderGeometry(.07,.09,4.6,6),new THREE.MeshLambertMaterial({color:0x5b6570}));
    p.position.y=2.3;g.add(p);
    const a=new THREE.Mesh(new THREE.BoxGeometry(.12,.1,1.1),new THREE.MeshLambertMaterial({color:0x5b6570}));
    a.position.set(0,4.5,.5);g.add(a);
    const l=new THREE.Mesh(new THREE.BoxGeometry(.2,.08,.4),new THREE.MeshBasicMaterial({color:0xfff2b8}));
    l.position.set(0,4.42,.95);g.add(l);return g;}},
  bench:{r:.5,m:26,mk(){const g=new THREE.Group();
    const s=new THREE.Mesh(new THREE.BoxGeometry(1.5,.08,.45),new THREE.MeshLambertMaterial({color:0x9a6b3f}));
    s.position.y=.45;g.add(s);
    const b=new THREE.Mesh(new THREE.BoxGeometry(1.5,.4,.07),new THREE.MeshLambertMaterial({color:0x9a6b3f}));
    b.position.set(0,.72,-.2);g.add(b);
    const l=new THREE.Mesh(new THREE.BoxGeometry(1.3,.42,.35),new THREE.MeshLambertMaterial({color:0x4a4f57}));
    l.position.y=.22;g.add(l);return g;}},
  barrel:{r:.35,m:20,mk(){const m=new THREE.Mesh(new THREE.CylinderGeometry(.32,.32,.9,10),
    new THREE.MeshLambertMaterial({color:0xd0662a}));m.position.y=.45;
    const g=new THREE.Group();g.add(m);return g;}},
};
function makeProp(type,x,y,z,yaw){
  const def=PROP_DEFS[type];
  const mesh=def.mk();mesh.position.set(x,y,z);mesh.rotation.y=yaw;
  return{type,mesh,def,home:{x,y,z,yaw},vel:V3(0,0,0),angVel:V3(0,0,0),awake:false,gone:false};}

/* prop vs vehicles — called from Vehicle.step */
function hitProps(veh){
  const props=veh.world.props,b=veh.body;
  for(let i=0;i<props.length;i++){
    const p=props[i];if(p.gone)continue;
    _t6.copy(p.mesh.position);_t6.y+=.4;
    _t7.copy(_t6).sub(b.pos);
    if(_t7.lengthSq()>36)continue;
    b.worldToLocal(_t6,_t8);
    const h=b.half,r=p.def.r;
    const cx=clamp(_t8.x,-h.x,h.x),cy=clamp(_t8.y,-h.y,h.y),cz=clamp(_t8.z,-h.z,h.z);
    const dx=_t8.x-cx,dy=_t8.y-cy,dz=_t8.z-cz;
    const d2=dx*dx+dy*dy+dz*dz;
    if(d2<r*r){
      _t9.set(cx,cy,cz);b.localToWorld(_t9,_t6);   // contact on car surface
      _t7.copy(_t6).sub(b.pos);
      b.velAt(_t7,_t8);
      const sp=_t8.length();
      if(sp>1){
        p.awake=true;
        p.vel.copy(_t8).multiplyScalar(1.15);
        p.vel.y+=sp*.28+1;
        p.angVel.set((Math.random()-.5)*8,(Math.random()-.5)*8,(Math.random()-.5)*8);
        b.vel.multiplyScalar(1-Math.min(.08,p.def.m/veh.spec.mass*.4));
        Fx.propHit(p,sp);}}}
}
function stepProps(world,dt){
  for(const p of world.props){
    if(!p.awake||p.gone)continue;
    p.vel.y-=GRAV*dt;
    p.mesh.position.addScaledVector(p.vel,dt);
    p.mesh.rotation.x+=p.angVel.x*dt;p.mesh.rotation.y+=p.angVel.y*dt;p.mesh.rotation.z+=p.angVel.z*dt;
    const gy=world.height(p.mesh.position.x,p.mesh.position.z);
    if(p.mesh.position.y<gy){
      p.mesh.position.y=gy;
      if(p.vel.y<0)p.vel.y*=-.3;
      p.vel.x*=.82;p.vel.z*=.82;p.angVel.multiplyScalar(.8);
      if(p.vel.lengthSq()<.05){p.awake=false;}}
    if(p.mesh.position.y<-40)p.gone=true;}
}
function resetProps(world){
  for(const p of world.props){
    p.gone=false;p.awake=false;p.vel.set(0,0,0);p.angVel.set(0,0,0);
    p.mesh.position.set(p.home.x,p.home.y,p.home.z);
    p.mesh.rotation.set(0,p.home.yaw,0);}
}
/* ============================================================
   Map definitions (6 built-in + custom loader)
   ============================================================ */
const S_ASP=SURF_ID.asphalt,S_GRS=SURF_ID.grass,S_SND=SURF_ID.sand,S_GRV=SURF_ID.gravel,
      S_ICE=SURF_ID.ice,S_SNW=SURF_ID.snow,S_CRB=SURF_ID.curb,S_WET=SURF_ID.wet,S_WLK=SURF_ID.walk;

const MAPS=[
/* ---------- 1. 프루빙 그라운드 ---------- */
{id:"proving",name:"프루빙 그라운드",icon:"🧪",desc:"가속로·충돌벽·램프·슬라럼·스키드패드·낙하 타워",
 modes:["free","crash","drift"],
 build(){
  const mb=new MapBuilder(560,224),w=mb.world;
  mb.fill((x,z)=>[0,S_ASP]);
  // perimeter grass ring
  mb.fill2=null;
  const half=270;
  for(let j=0;j<=w.res;j++)for(let i=0;i<=w.res;i++){
    const x=i*w.cell-280,z=j*w.cell-280;
    if(Math.abs(x)>half-18||Math.abs(z)>half-18)w.setS(i,j,S_GRS);}
  // drag strip lane markings (curb stripes)
  for(let z=-200;z<=200;z+=50)mb.stamp(-80,z,2.2,(i,j)=>w.setS(i,j,S_CRB));
  // crash walls (concrete + barrier) at end of strip
  mb.box(-80,2.2,232,26,4.4,3,0x9aa2ab,{mu:.6,bounce:.05,tag:"wall"});
  mb.box(-40,1,210,14,2,2,0xd8433b,{mu:.5,bounce:.3,tag:"barrier"});
  // speed trap
  w.triggers=[{x:-80,z:180,r:10,type:"trap"}];
  // ramps 15/30/45
  mb.ramp(30,40,0,15,16,10);mb.ramp(52,40,0,30,12,10);mb.ramp(74,40,0,45,9,10);
  // kick ramp (banked → flips)
  mb.box(30,-0,120,10,1,9,0xc7742f,{pitch:-18*DEG,roll:14*DEG,mu:1,tag:"kick"});
  // slalom cones
  for(let k=0;k<8;k++)mb.prop("cone",10+((k%2)*8-4),-60-k*22);
  // 과속방지턱 시험 구간
  for(let k=0;k<5;k++)mb.bump(-20,-60-k*16,0,11);
  // skidpad R30 marking
  for(let a=0;a<Math.PI*2;a+=.05){
    mb.stamp(150+Math.cos(a)*30,-120+Math.sin(a)*30,1.6,(i,j)=>w.setS(i,j,S_CRB));}
  // drop towers 10m & 20m with access ramps
  const tower=(x,z,h)=>{
    mb.box(x,h-.5,z,26,1,26,0x7f8791,{mu:1,tag:"tower"});             // deck
    const rl=h/Math.tan(22*DEG);
    mb.box(x,h*.5-.5,z-13-rl*.5+.2,12,1,rl/Math.cos(22*DEG),0x8f98a3,{pitch:-22*DEG,mu:1,tag:"ramp"});
    for(const s of[-1,1])mb.box(x+s*13.2,h+.6,z,.4,1.6,26,0xb9c2cc,{mu:.4,tag:"rail"});}; // 전방(+z) 개방 → 낙하
  tower(160,120,10);tower(220,140,20);
  // barrels near barrier
  for(let k=0;k<4;k++)mb.prop("barrel",-40+k*3,200);
  for(let k=0;k<8;k++)mb.baked(k%2?"trees":"treesTall",-262+k*70,262,11,k,{});
  w.spawn={x:-80,z:-220,yaw:0};
  return mb.finalize(this);}},

/* ---------- 2. 네오시티 ---------- */
{id:"city",name:"네오시티",icon:"🏙️",desc:"6×6 블록 시가지 — 골목·고가도로·로터리·파괴 오브젝트",
 modes:["free","time","race","drift"],
 build(){
  const mb=new MapBuilder(640,224),w=mb.world;
  const pitch=96,half=288;
  mb.fill((x,z)=>{
    // roads on grid lines every 96m, width 16
    const rx=Math.abs(((x%pitch)+pitch*1.5)%pitch-pitch*.5),rz=Math.abs(((z%pitch)+pitch*1.5)%pitch-pitch*.5);
    const road=rx<8||rz<8;
    const walk=!road&&(rx<11||rz<11);
    if(Math.abs(x)>half||Math.abs(z)>half)return[0,S_GRS];
    return[0,road?S_ASP:walk?S_WLK:S_GRS];});
  // 차선 (도로 중앙 점선)
  for(let j=0;j<=w.res;j++)for(let i=0;i<=w.res;i++){
    const x=i*w.cell-320,z=j*w.cell-320;
    if(Math.abs(x)>half||Math.abs(z)>half)continue;
    if(w.sMap[w.idx(i,j)]!==S_ASP)continue;
    const rx=Math.abs(((x%pitch)+pitch*1.5)%pitch-pitch*.5),rz=Math.abs(((z%pitch)+pitch*1.5)%pitch-pitch*.5);
    if((rx<.9&&((z%9+9)%9)<4&&rz>10)||(rz<.9&&((x%9+9)%9)<4&&rx>10))w.setS(i,j,SURF_ID.lane);}
  // roundabout at center + 분수
  mb.stamp(0,0,22,(i,j,d)=>{w.setS(i,j,S_ASP);});
  mb.stamp(0,0,9,(i,j,d)=>{w.setS(i,j,S_WLK);});
  mb.baked("fountain",0,0,15,0,{y:0,collide:true,shrink:.75});
  // 베이크 건물 (Kenney City Builder Kit)
  let seed=7;const rnd=()=>{seed=(seed*16807)%2147483647;return seed/2147483647;};
  const BLD=["bldA","bldB","bldC","bldD","garage"];
  for(let bx=-2.5;bx<=2.5;bx++)for(let bz=-2.5;bz<=2.5;bz++){
    if(Math.abs(bx)<1&&Math.abs(bz)<1)continue;
    const cx=bx*pitch,cz=bz*pitch;
    const n=1+((rnd()*2)|0);
    for(let k=0;k<n;k++){
      const nm=BLD[(rnd()*5)|0];
      const sc=22+rnd()*16;
      const ox=cx+(rnd()-.5)*(66-sc),oz=cz+(rnd()-.5)*(66-sc);
      mb.baked(nm,ox,oz,sc,((rnd()*4)|0)*Math.PI/2,{y:0,collide:true,shrink:.92});}
    // 블록 코너 가로수
    if(rnd()<.75)mb.baked(rnd()<.5?"trees":"treesTall",cx+30,cz+30,11+rnd()*4,rnd()*6,{y:0});}
  // overpass across x axis (z=~ -96 row): ramps + elevated deck
  const oy=7;
  mb.box(-40,oy-.5,-96,160,1,14,0x69707c,{mu:1,tag:"deck"});
  const rl=oy/Math.tan(9*DEG);
  mb.box(-120-rl*.5+.1,oy*.5-.5,-96,rl/Math.cos(9*DEG),1,14,0x7d8591,{roll:9*DEG,mu:1,tag:"ramp"});
  mb.box(40+rl*.5-.1,oy*.5-.5,-96,rl/Math.cos(9*DEG),1,14,0x7d8591,{roll:-9*DEG,mu:1,tag:"ramp"});
  for(const s of[-1,1])mb.box(-40,oy+.5,-96+s*7.2,160,1.2,.4,0xb9c2cc,{mu:.4,tag:"rail"});
  // props along roads
  for(let k=-2;k<=2;k++){
    mb.prop("lamp",12,k*pitch+30,Math.PI);mb.prop("lamp",-12,k*pitch-30,0);
    mb.prop("sign",k*pitch+12,12,0);mb.prop("bench",k*pitch-14,-14,Math.PI/2);}
  // 과속방지턱: 로터리 진입로 4곳 + 스쿨존 2곳
  mb.bump(34,0,Math.PI/2,14);mb.bump(-34,0,Math.PI/2,14);
  mb.bump(0,34,0,14);mb.bump(0,-34,0,14);
  mb.bump(96,44,0,14);mb.bump(96,-44,0,14);
  mb.bump(-52,-96,Math.PI/2,14);mb.bump(52,-96,Math.PI/2,14);
  // city loop route (time attack / race)
  const loop=samplePath([[-96,-192],[96,-192],[192,-96],[192,96],[96,192],[-96,192],[-192,96],[-192,-96]],true,160);
  w.checkpoints=pathCheckpoints(loop,20,15);
  w.waypoints=pathWaypoints(loop,true,32);
  w.spawn={x:-96,z:-192,yaw:Math.PI/2};
  mb.paintLanes();
  return mb.finalize(this);}},

/* ---------- 3. 미시령 와인딩 ---------- */
{id:"mountain",name:"미시령 와인딩",icon:"⛰️",desc:"헤어핀 7개 다운힐 — 가드레일 너머는 낭떠러지",
 modes:["free","time"],
 build(){
  const mb=new MapBuilder(760,224),w=mb.world;
  // base mountain: high at -x,-z corner
  mb.fill((x,z)=>{
    const d=Math.hypot(x+380,z+380)/760;
    let h=200*clamp(1-d,0,1);
    h+=8*Math.sin(x*.02)*Math.cos(z*.023)+4*Math.sin(x*.07+1)*Math.sin(z*.06);
    return[h,S_GRS];});
  // switchback road: hairpins descending
  const ctrl=[];let e=190;
  const xs=[-320,60,-40,120,-90,160,-140,200,-180,240];
  for(let k=0;k<xs.length;k++){
    const z=-330+k*68;e-=19;
    ctrl.push([xs[k],z,Math.max(e,2)]);}
  ctrl.push([320,330,2]);
  const road=samplePath(ctrl.map(c=>[c[0],c[1],c[2]]),false,420);
  mb.paintPath(road,11,S_ASP,true,true);
  railAlong(mb,road,11,0xc7ccd4);
  {let sd=23;const rr=()=>{sd=(sd*48271)%2147483647;return sd/2147483647;};
   for(let k=0;k<26;k++){
     const p=road[(rr()*road.length)|0];
     const off=18+rr()*40,ang=rr()*Math.PI*2;
     const tx=p.x+Math.cos(ang)*off,tz=p.z+Math.sin(ang)*off;
     if(w.surf(tx,tz)===S_GRS)mb.baked("treesTall",tx,tz,9+rr()*5,rr()*6,{});}}
  mb.paintLanes();
  w.checkpoints=pathCheckpoints(road,42,15);
  w.waypoints=pathWaypoints(road,false,30);
  w.spawn={x:road[2].x,z:road[2].z,yaw:Math.atan2(road[6].x-road[2].x,road[6].z-road[2].z)};
  w.route="sprint";
  return mb.finalize(this);}},

/* ---------- 4. 황야 ---------- */
{id:"dunes",name:"황야",icon:"🏜️",desc:"1km² 오프로드 — 모래언덕·바위밭·점프 절벽·마른 강바닥",
 modes:["free","drift"],
 build(){
  const mb=new MapBuilder(1000,224),w=mb.world;
  mb.fill((x,z)=>{
    let h=6*Math.sin(x*.027)*Math.cos(z*.031)+3.5*Math.sin(x*.071+2)*Math.cos(z*.057+1)+1.5*Math.sin(x*.15)*Math.cos(z*.13);
    // plateau with jump cliff on east side
    const p=clamp((x-160)/60,0,1);h+=16*p*p*(3-2*p);
    // dry riverbed winding north-south
    const rb=Math.abs(x+180+60*Math.sin(z*.012));
    if(rb<26)h-=4*(1-rb/26);
    let s=S_SND;
    if(rb<20)s=S_GRV;
    if(p>.6)s=S_GRV;
    return[h,s];});
  // rocks
  let seed=3;const rnd=()=>{seed=(seed*48271)%2147483647;return seed/2147483647;};
  for(let k=0;k<26;k++){
    const x=(rnd()-.5)*860,z=(rnd()-.5)*860;
    const sc=1.2+rnd()*3;
    mb.box(x,w.height(x,z)+sc*.32,z,sc*2,sc,sc*1.6,0x7a7169,{yaw:rnd()*3,roll:(rnd()-.5)*.4,mu:.8,tag:"rock"});}
  // desert ramp + barrels
  mb.ramp(120,0,Math.PI/2,20,14,12,0xa08055);
  for(let k=0;k<5;k++)mb.prop("barrel",-40+k*4,60);
  w.spawn={x:-300,z:-300,yaw:Math.PI/4};
  return mb.finalize(this);}},

/* ---------- 5. 빙판 호수 ---------- */
{id:"ice",name:"빙판 호수",icon:"❄️",desc:"μ0.15 초저마찰 — 드리프트 서클과 눈벽 안전지대",
 modes:["free","drift"],
 build(){
  const mb=new MapBuilder(520,192),w=mb.world;
  mb.fill((x,z)=>{
    const d=Math.hypot(x,z);
    if(d<170)return[0,S_ICE];
    if(d<225)return[.3+(d-170)*.02,S_SNW];
    return[2+(d-225)*.06,S_SNW];});
  // drift circles
  for(const r of[35,80])
    for(let a=0;a<Math.PI*2;a+=.04)
      mb.stamp(Math.cos(a)*r,Math.sin(a)*r,1.4,(i,j)=>w.setS(i,j,S_CRB));
  // snow wall ring
  for(let a=0;a<Math.PI*2;a+=Math.PI/26){
    const x=Math.cos(a)*205,z=Math.sin(a)*205;
    mb.box(x,w.height(x,z)+.9,z,4,1.8,22,0xf0f4f8,{yaw:-a,mu:.3,bounce:.35,tag:"snow"});}
  for(let k=0;k<6;k++)mb.prop("cone",Math.cos(k)*35,Math.sin(k)*35);
  w.spawn={x:0,z:-120,yaw:0};
  return mb.finalize(this);}},

/* ---------- 6. 선셋 레이스웨이 ---------- */
{id:"raceway",name:"선셋 레이스웨이",icon:"🏁",desc:"3.1km 12코너 서킷 — 타임어택 기준 맵",
 modes:["free","time","race","drift"],
 build(){
  const mb=new MapBuilder(820,224),w=mb.world;
  mb.fill((x,z)=>[1.5*Math.sin(x*.01)*Math.cos(z*.012),S_GRS]);
  const ctrl=[[-300,-220],[-60,-300],[140,-260],[240,-140],[160,-40],[260,60],[280,200],[120,290],
              [-60,230],[-160,290],[-300,220],[-350,60],[-260,-40],[-340,-120]];
  const road=samplePath(ctrl,true,480);
  mb.paintPath(road,13,S_ASP,true,true);
  // curbs: paint stripe bands at corners (high curvature areas)
  for(let i=2;i<road.length-2;i+=2){
    const a=road[i-2],b=road[i],c=road[i+2];
    const ang=Math.abs(Math.atan2(c.x-b.x,c.z-b.z)-Math.atan2(b.x-a.x,b.z-a.z));
    if(ang>.045&&ang<3){
      const dx=c.x-a.x,dz=c.z-a.z,l=Math.hypot(dx,dz)||1;
      for(const s of[-1,1])mb.stamp(b.x+dz/l*s*7.2,b.z-dx/l*s*7.2,1.5,(ii,jj)=>w.setS(ii,jj,S_CRB));}}
  // tire walls at hard corners
  for(let i=0;i<road.length-4;i+=8){
    const a=road[i],b=road[i+4];
    const ang2=Math.atan2(b.x-a.x,b.z-a.z);
    const mid=road[i+2];
    const dx=b.x-a.x,dz=b.z-a.z,l=Math.hypot(dx,dz)||1;
    const cv=Math.abs(Math.atan2(road[(i+8)%road.length].x-b.x,road[(i+8)%road.length].z-b.z)-ang2);
    if(cv>.35&&cv<3)for(const s of[-1,1])
      mb.box(mid.x+dz/l*s*13,w.height(mid.x+dz/l*s*13,mid.z-dx/l*s*13)+.5,mid.z-dx/l*s*13,
        1.2,1,7,s>0?0xd8433b:0xe8e8e8,{yaw:ang2,mu:.6,bounce:.3,tag:"tirewall"});}
  // grandstand + 나무
  mb.box(-180,4,-268,60,8,10,0x39424e,{mu:.5,tag:"stand"});
  {let sd=17;const rr=()=>{sd=(sd*48271)%2147483647;return sd/2147483647;};
   for(let k=0;k<22;k++){
     const a=rr()*Math.PI*2,r=120+rr()*220;
     const tx=Math.cos(a)*r,tz=Math.sin(a)*r*.9;
     if(w.surf(tx,tz)===S_GRS)mb.baked(rr()<.5?"trees":"treesTall",tx,tz,10+rr()*5,rr()*6,{});}}
  w.checkpoints=pathCheckpoints(road,30,16);
  mb.paintLanes();
  w.waypoints=pathWaypoints(road,true,52);
  w.spawn={x:road[0].x,z:road[0].z,yaw:Math.atan2(road[4].x-road[0].x,road[4].z-road[0].z)};
  return mb.finalize(this);}},
];

/* ---------- 7. 그랜드 시티 (오픈월드) ---------- */
MAPS.push(
{id:"grand",name:"그랜드 시티",icon:"🌆",desc:"1.4km² 오픈월드 — 도심·순환고속도로·언덕·호수·공업지구·방지턱",
 modes:["free","time","race","drift"],
 build(){
  const mb=new MapBuilder(1200,224),w=mb.world;
  mb.fill((x,z)=>{
    let h=1.2*Math.sin(x*.008)*Math.cos(z*.009);
    const hd=Math.hypot(x-380,z+380);h+=22*Math.exp(-hd*hd/64800);   // 언덕(북동)
    const h2=Math.hypot(x-260,z+170);h+=9*Math.exp(-h2*h2/28800);
    const ld=Math.hypot(x+350,z-300);                                 // 호수(북서)
    let s=S_GRS;
    if(ld<95){h=Math.min(h,-.35);s=S_WET;}
    else if(ld<115){h*=.3;s=S_SND;}
    return[h,s];});
  // 도심 격자 (pitch 90, 5x5)
  for(let k=-2;k<=2;k++){
    mb.paintPath([{x:-185,y:0,z:k*90},{x:185,y:0,z:k*90}],14,S_ASP,true,true);
    mb.paintPath([{x:k*90,y:0,z:-185},{x:k*90,y:0,z:185}],14,S_ASP,true,true);}
  // 순환 고속도로 (r≈420) — 언덕을 절개하며 통과
  const ring=samplePath([[420,0],[300,300],[0,420],[-300,300],[-420,0],[-300,-300],[0,-420],[297,-297]],true,360);
  mb.paintPath(ring,19,S_ASP,true,true);
  railAlong(mb,ring,19,0xb9c2cc);
  // 연결로 4방향
  for(const[a,b]of[[[185,0],[418,0]],[[-185,0],[-418,0]],[[0,185],[0,418]],[[0,-185],[0,-418]]])
    mb.paintPath([{x:a[0],y:0,z:a[1]},{x:b[0],y:0,z:b[1]}],14,S_ASP,true);
  // 베이크 건물
  let seed=11;const rnd=()=>{seed=(seed*16807)%2147483647;return seed/2147483647;};
  const BLD2=["bldA","bldB","bldC","bldD"];
  for(let bx=-2;bx<2;bx++)for(let bz=-2;bz<2;bz++){
    const cx=bx*90+45,cz=bz*90+45;
    for(let k=0;k<2;k++){
      const sc=20+rnd()*16;
      mb.baked(BLD2[(rnd()*4)|0],cx+(rnd()-.5)*(60-sc),cz+(rnd()-.5)*(60-sc),sc,
        ((rnd()*4)|0)*Math.PI/2,{y:0,collide:true,shrink:.92});}
    if(rnd()<.6)mb.baked("trees",cx+26,cz-26,12,rnd()*6,{y:0});}
  // 교외 주택(남서) — 차고 모델 + 나무
  for(let k=0;k<7;k++){
    const hx2=-330+((k%3)*36),hz2=-260-((k/3)|0)*40;
    mb.baked("garage",hx2,hz2,14,((k%4))*Math.PI/2,{collide:true,shrink:.9});
    if(k%2)mb.baked("treesTall",hx2+18,hz2+8,10+(k%3)*2,k,{});}
  for(let k=0;k<4;k++)
    mb.box(300+k*46,w.height(300+k*46,330)+5,330,38,10,26,0x77808c,{mu:.5,tag:"warehouse"});
  for(let k=0;k<6;k++)mb.prop("barrel",310+k*5,300);
  // 방지턱: 도심 스쿨존
  for(const[bx,bz,yaw]of[[45,0,Math.PI/2],[-45,0,Math.PI/2],[0,45,0],[0,-45,0],[90,50,0],[-90,-50,0]])
    mb.bump(bx,bz,yaw,13);
  // 언덕 비포장길
  const dirt=samplePath([[220,-140],[300,-230],[380,-330],[430,-390]],false,80);
  for(const p of dirt)mb.stamp(p.x,p.z,6,(i,j)=>w.setS(i,j,SURF_ID.gravel));
  // 언덕·호수 나무
  for(let k=0;k<16;k++){
    const tx=240+rnd()*220,tz=-160-rnd()*220;
    mb.baked(rnd()<.5?"trees":"treesTall",tx,tz,10+rnd()*5,rnd()*6,{});}
  for(let k=0;k<6;k++)mb.baked("treesTall",-350+Math.cos(k*1.05)*130,300+Math.sin(k*1.05)*130,11,k,{});
  // 가로등·표지판
  for(let k=-1;k<=1;k++){mb.prop("lamp",10,k*90+25,Math.PI);mb.prop("sign",k*90+10,10,0);}
  w.checkpoints=pathCheckpoints(ring,24,18);
  w.waypoints=pathWaypoints(ring,true,50);
  w.spawn={x:0,z:-60,yaw:0};
  mb.paintLanes();
  return mb.finalize(this);}});

/* ---------- custom map from editor tiles ---------- */
const ED_TILES=[
  {id:"road", name:"직선로", col:"#4a5058"},
  {id:"curve",name:"커브",   col:"#5a6270"},
  {id:"cross",name:"교차로", col:"#3e444d"},
  {id:"ramp", name:"램프",   col:"#c7742f"},
  {id:"wall", name:"벽",     col:"#9aa2ab"},
  {id:"bump", name:"방지턱", col:"#e8b93c"},
  {id:"cone", name:"콘",     col:"#ff7518"},
  {id:"check",name:"체크포인트",col:"#3ddc84"},
  {id:"start",name:"출발점", col:"#ffd23e"},
  {id:"erase",name:"지우개", col:"#20242b"},
];
function buildCustomMap(data){
  const N=24,TS=20,size=N*TS+80;
  const mb=new MapBuilder(size,192),w=mb.world;
  mb.fill(()=>[0,S_GRS]);
  const at=(gx,gz)=>({x:(gx-N/2+.5)*TS,z:(gz-N/2+.5)*TS});
  const cps=[];
  for(const t of data.tiles){
    const{x,z}=at(t.x,t.z),rot=t.r*Math.PI/2;
    switch(t.t){
      case"road":mb.paintPath([{x:x-Math.sin(rot)*TS/2,y:0,z:z-Math.cos(rot)*TS/2},
                      {x:x+Math.sin(rot)*TS/2,y:0,z:z+Math.cos(rot)*TS/2}],12,S_ASP,false);break;
      case"cross":mb.paintPath([{x:x-TS/2,y:0,z},{x:x+TS/2,y:0,z}],12,S_ASP,false);
        mb.paintPath([{x,y:0,z:z-TS/2},{x,y:0,z:z+TS/2}],12,S_ASP,false);break;
      case"curve":{
        // quarter arc: north-edge mid → east-edge mid (then rotated clockwise by r)
        const p=[],ca=Math.cos(rot),sa=Math.sin(rot);
        for(let a=0;a<=8;a++){
          const t2=a/8*Math.PI/2;
          const lx=TS/2-Math.cos(t2)*TS/2,lz=-TS/2+Math.sin(t2)*TS/2;
          p.push({x:x+lx*ca-lz*sa,y:0,z:z+lx*sa+lz*ca});}
        mb.paintPath(p,12,S_ASP,false);break;}
      case"ramp":mb.ramp(x,z,rot,20,14,10);break;
      case"wall":mb.box(x,1.2,z,TS*.9,2.4,1.2,0x9aa2ab,{yaw:rot,mu:.6,tag:"wall"});break;
      case"bump":mb.bump(x,z,rot,12);break;
      case"cone":mb.prop("cone",x,z);break;
      case"check":cps.push({x,z,r:12,ord:t.ord||0});break;
      case"start":w.spawn={x,z,yaw:rot+Math.PI};break;}}
  cps.sort((a,b)=>a.ord-b.ord);
  w.checkpoints=cps;
  if(cps.length>1)w.waypoints=cps.map(c=>({x:c.x,z:c.z,v:20}));
  w.route=cps.length>1?"loop":null;
  return mb.finalize({id:"custom:"+data.name,name:data.name,icon:"🛠️",custom:true,
    modes:cps.length>1?["free","time"]:["free"]});
}
/* ============================================================
   FX — particle pools, skid marks, debris, slow-mo bookkeeping
   ============================================================ */
const Fx=(()=>{
  let scene=null,quality=1,softTex=null;
  function getSoftTex(){
    if(softTex)return softTex;
    const c=document.createElement("canvas");c.width=c.height=64;
    const x=c.getContext("2d");
    const g=x.createRadialGradient(32,32,2,32,32,30);
    g.addColorStop(0,"rgba(255,255,255,1)");g.addColorStop(.6,"rgba(255,255,255,.55)");
    g.addColorStop(1,"rgba(255,255,255,0)");
    x.fillStyle=g;x.fillRect(0,0,64,64);
    softTex=new THREE.CanvasTexture(c);
    return softTex;}
  /* particle pool */
  function makePool(n,size,color,additive,gravity,drag){
    const geo=new THREE.BufferGeometry();
    const pos=new Float32Array(n*3);pos.fill(1e5);
    geo.setAttribute("position",new THREE.BufferAttribute(pos,3));
    const mat=new THREE.PointsMaterial({size,color,transparent:true,opacity:.9,map:getSoftTex(),
      blending:additive?THREE.AdditiveBlending:THREE.NormalBlending,depthWrite:false,sizeAttenuation:true});
    const pts=new THREE.Points(geo,mat);pts.frustumCulled=false;
    return{n,pos,geo,pts,vel:new Float32Array(n*3),life:new Float32Array(n),maxLife:new Float32Array(n),
      head:0,gravity,drag,alive:0};}
  let sparks,smoke,shards,dust;
  const pools=[];
  function emit(p,x,y,z,vx,vy,vz,life){
    const i=p.head;p.head=(p.head+1)%p.n;
    p.pos[i*3]=x;p.pos[i*3+1]=y;p.pos[i*3+2]=z;
    p.vel[i*3]=vx;p.vel[i*3+1]=vy;p.vel[i*3+2]=vz;
    p.life[i]=life;p.maxLife[i]=life;}
  function stepPool(p,dt){
    let any=false;
    for(let i=0;i<p.n;i++){
      if(p.life[i]<=0)continue;
      any=true;p.life[i]-=dt;
      if(p.life[i]<=0){p.pos[i*3+1]=1e5;continue;}
      p.vel[i*3+1]-=p.gravity*dt;
      p.vel[i*3]*=p.drag;p.vel[i*3+1]*=p.drag;p.vel[i*3+2]*=p.drag;
      p.pos[i*3]+=p.vel[i*3]*dt;p.pos[i*3+1]+=p.vel[i*3+1]*dt;p.pos[i*3+2]+=p.vel[i*3+2]*dt;}
    if(any)p.geo.attributes.position.needsUpdate=true;}

  /* skid marks */
  let skidMesh,skidN=520,skidHead=0;
  const _m4=new THREE.Matrix4(),_q1=new THREE.Quaternion(),_s1=V3(1,1,1),_e1=new THREE.Euler();

  /* debris */
  const debris=[];const DEBRIS_MAX=12;

  function init(sc){
    scene=sc;
    sparks=makePool(160,.14,0xffb25e,true,14,.985);
    smoke=makePool(140,1.1,0x8a8f96,false,-1.5,.97);
    shards=makePool(120,.09,0xbfe4f2,true,18,.99);
    dust=makePool(160,.9,0xb9a684,false,1,.96);
    pools.length=0;pools.push(sparks,smoke,shards,dust);
    for(const p of pools)scene.add(p.pts);
    const g=new THREE.PlaneGeometry(.3,.72);g.rotateX(-Math.PI/2);
    skidMesh=new THREE.InstancedMesh(g,new THREE.MeshBasicMaterial({color:0x14171c,transparent:true,opacity:.45,depthWrite:false}),skidN);
    skidMesh.frustumCulled=false;
    _m4.makeScale(0,0,0);
    for(let i=0;i<skidN;i++)skidMesh.setMatrixAt(i,_m4);
    skidMesh.instanceMatrix.needsUpdate=true;
    scene.add(skidMesh);
  }
  function reset(){
    for(const p of pools){p.life.fill(0);p.pos.fill(1e5);p.geo.attributes.position.needsUpdate=true;}
    _m4.makeScale(0,0,0);
    for(let i=0;i<skidN;i++)skidMesh.setMatrixAt(i,_m4);
    skidMesh.instanceMatrix.needsUpdate=true;
    for(const d of debris)finishDebris(d,true);
    debris.length=0;
  }
  function setQuality(q){quality=q;}

  function skidMark(x,y,z,yaw){
    _e1.set(0,yaw,0);_q1.setFromEuler(_e1);
    _m4.compose(_t6.set(x,y+.025,z),_q1,_s1);
    skidMesh.setMatrixAt(skidHead,_m4);
    skidHead=(skidHead+1)%skidN;
    skidMesh.instanceMatrix.needsUpdate=true;}

  function impactFx(wp,n,dv){
    const cnt=Math.min(3+dv|0,16)*quality|0;
    for(let i=0;i<cnt;i++)
      emit(sparks,wp.x,wp.y,wp.z,
        n.x*3+(Math.random()-.5)*6,Math.random()*4+1,n.z*3+(Math.random()-.5)*6,.3+Math.random()*.4);
    if(dv>5)for(let i=0;i<cnt*.6;i++)
      emit(shards,wp.x,wp.y+.3,wp.z,(Math.random()-.5)*7,Math.random()*5,(Math.random()-.5)*7,.4+Math.random()*.5);
    Sfx.impact(clamp(dv/16,0,1));}
  function smokeAt(x,y,z,vx,vz,amt){
    if(Math.random()>amt*quality)return;
    emit(smoke,x,y,z,vx*.3+(Math.random()-.5),1+Math.random(),vz*.3+(Math.random()-.5),.8+Math.random()*.8);}
  function dustAt(x,y,z,amt){
    if(Math.random()>amt*quality)return;
    emit(dust,x,y+.2,z,(Math.random()-.5)*2,.8+Math.random(),(Math.random()-.5)*2,.5+Math.random()*.6);}
  function propHit(p,speed){
    Sfx.impact(clamp(speed/22,0,.55));
    for(let i=0;i<6;i++)
      emit(sparks,p.mesh.position.x,p.mesh.position.y+.4,p.mesh.position.z,
        (Math.random()-.5)*5,Math.random()*4,(Math.random()-.5)*5,.3);}

  /* debris: detached car part */
  function addDebris(mesh,veh,imp){
    if(debris.length>=DEBRIS_MAX)finishDebris(debris.shift(),true);
    mesh.updateWorldMatrix(true,false);
    const wp=V3(0,0,0),wq=new THREE.Quaternion(),ws=V3(1,1,1);
    mesh.matrixWorld.decompose(wp,wq,ws);
    if(mesh.parent)mesh.parent.remove(mesh);
    scene.add(mesh);
    mesh.position.copy(wp);mesh.quaternion.copy(wq);
    if(!(mesh.material.transparent)){mesh.material=mesh.material.clone();mesh.material.transparent=true;}
    mesh.material.opacity=1;
    const vel=V3(0,0,0);
    veh.body.velAt(_t6.copy(wp).sub(veh.body.pos),vel);
    vel.multiplyScalar(.8);vel.y+=2+Math.random()*2;
    if(imp)vel.addScaledVector(_t7.copy(imp.wp).sub(veh.body.pos).normalize(),2);
    debris.push({mesh,vel,angVel:V3((Math.random()-.5)*7,(Math.random()-.5)*7,(Math.random()-.5)*7),t:0});
  }
  function reclaimDebris(mesh){
    for(let i=0;i<debris.length;i++)
      if(debris[i].mesh===mesh){scene.remove(mesh);debris.splice(i,1);return;}
    if(mesh.parent===scene)scene.remove(mesh);
  }
  function finishDebris(d,now){
    if(scene&&d.mesh.parent===scene)scene.remove(d.mesh);}
  function step(dt,world){
    for(const p of pools)stepPool(p,dt);
    for(let i=debris.length-1;i>=0;i--){
      const d=debris[i];d.t+=dt;
      d.vel.y-=GRAV*dt;
      d.mesh.position.addScaledVector(d.vel,dt);
      d.mesh.rotation.x+=d.angVel.x*dt;d.mesh.rotation.y+=d.angVel.y*dt;d.mesh.rotation.z+=d.angVel.z*dt;
      const gy=world?world.height(d.mesh.position.x,d.mesh.position.z):0;
      if(d.mesh.position.y<gy+.1){
        d.mesh.position.y=gy+.1;
        if(d.vel.y<0)d.vel.y*=-.35;
        d.vel.x*=.85;d.vel.z*=.85;d.angVel.multiplyScalar(.75);}
      if(d.t>4)d.mesh.material.opacity=Math.max(0,1-(d.t-4));
      if(d.t>5){finishDebris(d);debris.splice(i,1);}}
  }
  return{init,reset,setQuality,skidMark,impactFx,smokeAt,dustAt,propHit,addDebris,reclaimDebris,step};
})();

/* ============================================================
   Camera
   ============================================================ */
class GameCamera{
  constructor(cam){
    this.cam=cam;
    this.modes=["chase","hood","bumper","top","free"];
    this.modeNames={chase:"체이스",hood:"후드",bumper:"범퍼",top:"탑뷰",free:"프리"};
    this.mode="chase";
    this.orbitYaw=0;this.orbitPitch=.32;this.dist=7;
    this.userT=0;this.shake=0;
    this.pos=V3(0,8,-10);this.look=V3(0,0,0);
  }
  cycle(){this.mode=this.modes[(this.modes.indexOf(this.mode)+1)%this.modes.length];
    return this.modeNames[this.mode];}
  onDrag(dx,dy){
    this.orbitYaw-=dx*.008;
    this.orbitPitch=clamp(this.orbitPitch+dy*.006,5*DEG,80*DEG);
    this.userT=2.2;}
  onPinch(scale){this.dist=clamp(this.dist/scale,3,14);this.userT=2.2;}
  update(dt,veh,world){
    const b=veh.body,sp=veh.speed;
    this.userT=Math.max(0,this.userT-dt);
    if(this.shake>0)this.shake=Math.max(0,this.shake-dt*2.4);
    const yaw=Math.atan2(2*(b.quat.w*b.quat.y+b.quat.x*b.quat.z),1-2*(b.quat.y*b.quat.y+b.quat.x*b.quat.x));
    let tx,ty,tz,lx,ly,lz;
    if(this.mode==="chase"||this.mode==="free"){
      const behind=(this.mode==="free"&&sp<1.5)||this.userT>0?this.orbitYaw+yaw:yaw;
      const recenter=this.mode==="chase"&&this.userT<=0;
      if(recenter)this.orbitYaw*=Math.max(0,1-dt*3);
      const d=this.dist+sp*.05,pi=this.orbitPitch;
      tx=b.pos.x-Math.sin(behind)*Math.cos(pi)*d;
      tz=b.pos.z-Math.cos(behind)*Math.cos(pi)*d;
      ty=b.pos.y+Math.sin(pi)*d;
      const ahead=this.mode==="chase"?clamp(sp*.25,0,7):0;
      lx=b.pos.x+Math.sin(yaw)*ahead;ly=b.pos.y+.6;lz=b.pos.z+Math.cos(yaw)*ahead;
      const k=this.mode==="chase"?1-Math.pow(.0018,dt):1-Math.pow(.0001,dt);
      this.pos.x+=(tx-this.pos.x)*k;this.pos.y+=(ty-this.pos.y)*k;this.pos.z+=(tz-this.pos.z)*k;
    }else if(this.mode==="hood"){
      _t6.set(0,veh.spec.body.hy*.55,veh.spec.body.hz*.35);b.localToWorld(_t6,this.pos);
      lx=b.pos.x+Math.sin(yaw)*30;ly=this.pos.y;lz=b.pos.z+Math.cos(yaw)*30;
    }else if(this.mode==="bumper"){
      _t6.set(0,-veh.spec.body.hy*.1,veh.spec.body.hz+.3);b.localToWorld(_t6,this.pos);
      lx=b.pos.x+Math.sin(yaw)*30;ly=this.pos.y;lz=b.pos.z+Math.cos(yaw)*30;
    }else{ // top
      this.pos.set(b.pos.x,b.pos.y+26+sp*.12,b.pos.z-6);
      lx=b.pos.x;ly=b.pos.y;lz=b.pos.z;}
    if(lx===undefined){lx=b.pos.x;ly=b.pos.y;lz=b.pos.z;}
    // keep above terrain
    if(world){const gy=world.height(this.pos.x,this.pos.z)+.5;if(this.pos.y<gy)this.pos.y=gy;}
    this.cam.position.copy(this.pos);
    if(this.shake>0&&Settings.camShake){
      this.cam.position.x+=(Math.random()-.5)*this.shake*.5;
      this.cam.position.y+=(Math.random()-.5)*this.shake*.5;}
    this.look.set(lx,ly,lz);
    this.cam.lookAt(this.look);
  }
}
/* ============================================================
   Game — state machine, fixed-step loop, modes, AI, HUD
   ============================================================ */
const MODES=[
 {id:"free", name:"자유주행",icon:"🚗",desc:"모든 맵 × 모든 차량. 손상·시간대 설정 자유."},
 {id:"crash",name:"크래시 테스트",icon:"💥",desc:"발사 속도를 정하고 벽에 충돌 — 슬로모 리플레이와 손상 리포트."},
 {id:"time", name:"타임어택",icon:"⏱️",desc:"랩타임 · 섹터 기록. 개인 베스트 영구 저장."},
 {id:"race", name:"AI 레이스",icon:"🏆",desc:"AI 3~5대와 접전. AI 차량에도 손상 물리 적용."},
 {id:"drift",name:"드리프트 스코어",icon:"🌀",desc:"각도×속도×콤보. 벽 스침 보너스, 스핀하면 콤보 소멸."},
 {id:"editor",name:"맵 에디터",icon:"🛠️",desc:"탑뷰 그리드에 도로·램프·벽 배치. 내 맵에서 바로 주행."},
];

const Game={
  state:"menu",paused:false,
  mode:"free",mapDef:null,world:null,mapGroup:null,
  veh:null,vis:null,ais:[],
  cam:null,acc:0,slowmoT:0,manualSlow:false,
  opts:{tod:"day",damage:true,laps:3,aiCount:3,color:0,carIdx:0,mapId:"proving"},
  physMs:0,shakeT:0,trapCool:0,
  /* mode-specific */
  crash:{phase:"idle",target:0,vTarget:60,peakG:0,impactV:0,parted:0,settleT:0,hitDone:false},
  timing:null,race:null,drift:null,

  startGame(){
    const o=this.opts;
    // build map
    if(this.mapGroup){scene.remove(this.mapGroup);disposeGroup(this.mapGroup);}
    let built;
    if(o.mapId.startsWith("custom:")){
      const data=Store.get("maps:"+o.mapId.slice(7),null);
      if(!data){toast("맵 데이터를 찾을 수 없습니다");return;}
      built=buildCustomMap(data);
    }else built=MAPS.find(m=>m.id===o.mapId).build();
    this.world=built.world;this.mapGroup=built.group;
    scene.add(this.mapGroup);
    this.mapDef=this.world.mapDef;
    // player vehicle
    if(this.vis)this.vis.dispose();
    const spec=CARS[o.carIdx];
    this.veh=new Vehicle(spec,this.world);
    this.veh.damageOn=o.damage||this.mode==="crash";
    this.vis=new CarVisual(spec,spec.colors[o.color%spec.colors.length]);
    this.vis.storeHomes();
    scene.add(this.vis.group);
    const sp=this.world.spawn;
    this.veh.reset(sp.x,sp.z,sp.yaw);
    this.applyAssists(this.veh);
    // AI
    for(const a of this.ais)a.vis.dispose();
    this.ais=[];
    if(this.mode==="race")this.setupRace();
    if(this.mode==="time")this.setupTiming();
    if(this.mode==="drift")this.drift={score:0,run:0,combo:1,driftT:0,idleT:0,best:getRec("drift|"+o.mapId)||0,wallBonus:false};
    if(this.mode==="crash"){this.crash.phase="idle";this.crash.vTarget=parseInt($("crashSpeed").value);this.placeCrashCar();}
    Fx.reset();resetProps(this.world);
    buildMinimap();
    Store.set("lastPlay",{mode:this.mode,carIdx:o.carIdx,mapId:o.mapId,color:o.color,tod:o.tod});
    applyTimeOfDay(o.tod);
    this.cam.mode="chase";this.cam.dist=spec.id==="titan"?10:7;this.cam.orbitYaw=0;
    this.cam.pos.set(sp.x-Math.sin(sp.yaw)*8,this.world.height(sp.x,sp.z)+4,sp.z-Math.cos(sp.yaw)*8);
    this.state="play";this.paused=false;this.acc=0;this.slowmoT=0;this.manualSlow=false;
    $("btnSlow").classList.remove("on");
    $("menu").classList.remove("on");$("hud").classList.add("on");$("editorScr").classList.remove("on");
    $("pausePanel").classList.remove("on");$("reportPanel").classList.remove("on");$("resultPanel").classList.remove("on");
    $("crashPanel").classList.toggle("on",this.mode==="crash");
    $("btnRepair").style.display=(this.mode==="free"||this.mode==="crash"||this.mode==="drift")?"":"none";
    Sfx.resume();
    updateModeWidget();
    toast(this.mapDef.name+" — "+spec.name,1800);
  },
  applyAssists(v){
    v.assists.abs=Settings.absOn;v.assists.tcs=Settings.tcsOn;
    v.assists.ctr=Settings.ctrSteer;v.assists.stab=Settings.stab;},
  exitToMenu(){
    this.state="menu";this.paused=false;
    $("hud").classList.remove("on");$("pausePanel").classList.remove("on");
    $("reportPanel").classList.remove("on");$("resultPanel").classList.remove("on");
    $("menu").classList.add("on");
    Sfx.engine(0,0,false);Sfx.skid(0);Sfx.wind(0);
    UI.show("home");},

  /* ---------- crash test ---------- */
  placeCrashCar(){
    const lanes=[-80,-40];
    const x=lanes[this.crash.target];
    this.veh.reset(x,-140,0,false);this.vis.repair();
    this.crash.phase="idle";
    updateModeWidget();},
  launch(){
    const c=this.crash,v=this.veh;
    this.vis.repair();v.clearDamage();
    const v0=c.vTarget/3.6;
    const lane=[-80,-40][c.target];
    v.reset(lane,Math.max(216-v0*2.2,-200),0,false);   // catapult: 즉시 목표 속도로 사출
    v.body.vel.set(0,0,v0);
    for(const w of v.wheels)w.omega=v0/w.radius;
    c.phase="run";c.peakG=0;c.impactV=0;c.parted=0;c.settleT=0;c.hitDone=false;
    v.peakG=0;
    toast("발사! "+c.vTarget+" km/h");Sfx.beep(660,.15,.2);},
  crashStep(dt){
    const c=this.crash,v=this.veh;
    if(c.phase==="run"){
      // auto-drive straight
      v.controlLock=true;
      const lane=[-80,-40][c.target];
      v.steerIn=clamp((lane-v.body.pos.x)*.08-v.body.vel.x*.05,-.3,.3);
      const kmh=v.fwdSpeed()*3.6;
      v.throttle=kmh<c.vTarget?1:0;v.brake=0;v.driveMode="D";
      if(c.hitDone){c.phase="settle";c.settleT=0;}
    }else if(c.phase==="settle"){
      v.controlLock=true;v.throttle=0;v.brake=.4;
      c.settleT+=dt;
      if((v.speed<.4&&c.settleT>1.2)||c.settleT>6){
        c.phase="report";v.controlLock=false;showCrashReport();}}
  },

  /* ---------- time attack ---------- */
  setupTiming(){
    const cps=this.world.checkpoints||[];
    this.timing={cp:0,lap:1,t:0,lapT:0,best:getRec("time|"+this.opts.mapId+"|"+CARS[this.opts.carIdx].id)||null,
      lastLap:null,sprint:this.world.route==="sprint",started:false,sectors:[],secN:Math.max(1,Math.floor(cps.length/3))};},
  timingStep(dt){
    const T=this.timing,cps=this.world.checkpoints;
    if(!cps||cps.length<2)return;
    if(T.started)T.t+=dt*1000;
    const cp=cps[T.cp%cps.length];
    const dx=this.veh.body.pos.x-cp.x,dz=this.veh.body.pos.z-cp.z;
    if(dx*dx+dz*dz<cp.r*cp.r){
      if(!T.started){T.started=true;T.t=0;bigMsg("GO!",700);}
      T.cp++;
      if(T.cp%T.secN===0&&T.cp<cps.length)Sfx.beep(880,.1,.1);
      if(T.sprint&&T.cp>=cps.length){this.finishSprint();return;}
      if(!T.sprint&&T.cp>=cps.length){
        T.cp=0;T.lastLap=T.t;
        if(!T.best||T.t<T.best){T.best=T.t;setRec("time|"+this.opts.mapId+"|"+CARS[this.opts.carIdx].id,T.t);
          bigMsg(fmtTime(T.t),1400,"NEW BEST LAP");Sfx.beep(1046,.3,.2);}
        else bigMsg(fmtTime(T.t),1200,"LAP");
        T.t=0;}}
  },
  finishSprint(){
    const T=this.timing;T.started=false;
    const key="time|"+this.opts.mapId+"|"+CARS[this.opts.carIdx].id;
    const best=getRec(key);
    const isNew=!best||T.t<best;
    if(isNew)setRec(key,T.t);
    showResult("⏱️ 완주!",[["기록",fmtTime(T.t)],["베스트",fmtTime(isNew?T.t:best)],
      isNew?["","🎉 신기록!"]:["","" ]]);},

  /* ---------- race ---------- */
  setupRace(){
    const n=clamp(this.opts.aiCount,3,5);
    const sp=this.world.spawn,cps=this.world.checkpoints;
    this.race={lap:1,laps:this.opts.laps,cp:0,done:false,t:0,
      prog:new Array(n+1).fill(0),rank:1};
    const perp=[Math.cos(sp.yaw),-Math.sin(sp.yaw)];
    for(let i=0;i<n;i++){
      const spec=CARS[(this.opts.carIdx+1+i)%CARS.length];
      const veh=new Vehicle(spec,this.world);
      veh.isAI=true;veh.damageOn=this.opts.damage;
      veh.assists.abs=veh.assists.tcs=true;veh.assists.ctr=veh.assists.stab=true;
      const row=1+((i/2)|0),side=(i%2?1:-1);
      veh.reset(sp.x+perp[0]*side*4-Math.sin(sp.yaw)*row*9,
                sp.z+perp[1]*side*4-Math.cos(sp.yaw)*row*9,sp.yaw);
      const vis=new CarVisual(spec,spec.colors[(i+2)%spec.colors.length]);
      vis.storeHomes();scene.add(vis.group);
      this.ais.push({veh,vis,wp:0,cp:0,lap:1,stuckT:0,revT:0,rubber:1,finished:false});}
    // player also offset to grid
    this.veh.reset(sp.x+perp[0]*4,sp.z+perp[1]*4,sp.yaw);
    this.race.count=0;this.race.countT=0;this.race.started=false;
  },
  raceStep(dt){
    const R=this.race,cps=this.world.checkpoints;
    if(!R.started){
      R.countT+=dt;
      this.veh.controlLock=true;this.veh.throttle=0;this.veh.brake=1;
      const num=3-(R.countT|0);
      if(num!==R.count){R.count=num;if(num>0){bigMsg(num,800);Sfx.beep(440,.12,.18);}}
      if(R.countT>=3){R.started=true;this.veh.controlLock=false;bigMsg("GO!",800);Sfx.beep(880,.3,.22);}
      return;}
    R.t+=dt*1000;
    // player checkpoint
    const cp=cps[R.cp%cps.length];
    const dx=this.veh.body.pos.x-cp.x,dz=this.veh.body.pos.z-cp.z;
    if(dx*dx+dz*dz<cp.r*cp.r*1.44){
      R.cp++;
      if(R.cp>=cps.length){R.cp=0;R.lap++;
        if(R.lap>R.laps&&!R.done){R.done=true;this.finishRace();}
        else if(!R.done)bigMsg("LAP "+R.lap+"/"+R.laps,1000);}}
    // ranks
    const progOf=(cpI,lap,x,z)=>{
      const c=cps[cpI%cps.length];
      return lap*10000+cpI*100-Math.hypot(x-c.x,z-c.z)*.1;};
    let ahead=0;
    const myP=progOf(R.cp,R.lap,this.veh.body.pos.x,this.veh.body.pos.z);
    for(const a of this.ais){
      const p=progOf(a.cp,a.lap,a.veh.body.pos.x,a.veh.body.pos.z);
      if(p>myP)ahead++;
      // rubberband ±5%
      a.rubber=clamp(1+(myP-p)/8000*.05,.95,1.05);}
    R.rank=ahead+1;
  },
  finishRace(){
    const R=this.race;
    setRecIfBetter("race|"+this.opts.mapId,R.rank,(a,b)=>a<b);
    showResult(R.rank===1?"🏆 우승!":"🏁 완주 — "+R.rank+"위",
      [["최종 순위",R.rank+" / "+(this.ais.length+1)],["레이스 타임",fmtTime(R.t)],["랩",R.laps+"랩"]]);},

  /* ---------- drift ---------- */
  driftStep(dt){
    const D=this.drift,v=this.veh;
    const sp=v.speed;
    v.body.vecToLocal(v.body.vel,_vA);
    const ang=Math.abs(Math.atan2(_vA.x,Math.abs(_vA.z)))/DEG;
    const drifting=ang>15&&ang<120&&sp>5&&v.grounded>1;
    if(drifting){
      D.driftT+=dt;D.idleT=0;
      D.combo=Math.min(5,D.combo+dt*.25);
      // wall proximity bonus
      let wall=false;
      for(const b of this.world.boxes){
        _vB.copy(v.body.pos).sub(b.c);
        if(_vB.lengthSq()<(b.r+2.2)*(b.r+2.2)){wall=true;break;}}
      D.wallBonus=wall;
      D.run+=ang*sp*dt*.08*D.combo*(wall?2:1);
    }else{
      D.idleT+=dt;
      if(ang>=120&&sp>4){ // spin!
        if(D.run>0){bigMsg("스핀!",800,"콤보 소멸");D.run*=.5;}
        D.combo=1;}
      if(D.idleT>1&&D.run>0){
        D.score+=D.run|0;
        if(D.run>500)toast("+"+(D.run|0)+"점 적립!");
        D.run=0;D.combo=1;
        if(D.score>D.best){D.best=D.score;setRec("drift|"+this.opts.mapId,D.score);}}}
    if(sp<1&&D.run>0&&D.idleT>2){D.run=0;D.combo=1;}
  },

  /* ---------- per-physics-step ---------- */
  physStep(dt){
    const v=this.veh;
    // input → player (unless locked)
    if(!v.controlLock)Input.applyTo(v);
    if(this.mode==="crash")this.crashStep(dt);
    if(this.mode==="race")this.raceStep(dt);
    if(this.mode==="time")this.timingStep(dt);
    if(this.mode==="drift")this.driftStep(dt);
    v.step(dt);
    for(const a of this.ais){stepAI(a,this.world,dt);a.veh.step(dt);}
    // car-car collisions
    const all=[v,...this.ais.map(a=>a.veh)];
    for(let i=0;i<all.length;i++)for(let j=i+1;j<all.length;j++)collideCars(all[i],all[j]);
    stepProps(this.world,dt);
    // world bounds / fall (안정성 4)
    for(const cv of all){
      const p=cv.body.pos;
      if(p.y<-50||Math.abs(p.x)>this.world.bounds+40||Math.abs(p.z)>this.world.bounds+40){
        const sp=this.world.spawn;
        cv.reset(sp.x+(Math.random()-.5)*6,sp.z+(Math.random()-.5)*6,sp.yaw,true);
        if(cv===v)toast("월드 경계 — 리스폰");}}
    // triggers (speed trap)
    if(this.trapCool>0)this.trapCool-=dt;
    if(this.world.triggers)for(const tr of this.world.triggers){
      const dx=v.body.pos.x-tr.x,dz=v.body.pos.z-tr.z;
      if(dx*dx+dz*dz<tr.r*tr.r&&this.trapCool<=0){
        this.trapCool=4;toast("📡 스피드 트랩: "+(v.speed*3.6).toFixed(1)+" km/h",2200);Sfx.beep(1200,.1,.15);}}
  },

  /* ---------- per-frame ---------- */
  frame(dt){
    if(this.state!=="play")return;
    const ts=(this.slowmoT>0||this.manualSlow)?.15:1;
    if(this.slowmoT>0)this.slowmoT-=dt;
    if(!this.paused){
      this.acc+=dt*ts;
      let steps=0;const t0=performance.now();
      while(this.acc>=PHYS_DT&&steps<10){this.physStep(PHYS_DT);this.acc-=PHYS_DT;steps++;}
      if(steps>=10)this.acc=0;
      this.physMs=performance.now()-t0;
      // consume impacts → deform + fx
      this.consumeImpacts(this.veh,this.vis,true);
      for(const a of this.ais)this.consumeImpacts(a.veh,a.vis,false);
      // wheels fx + sound
      this.wheelFx(dt*ts);
      Fx.step(dt*ts,this.world);
      const v=this.veh;
      Sfx.engine(v.rpm,v.throttle,true);
      Sfx.skid(v.skidMax*(v.grounded?1:0));
      Sfx.wind(v.speed);
      // flip prompt
      $("btnReset").classList.toggle("blink",v.flipT>3);
    }else{Sfx.engine(0,0,false);Sfx.skid(0);Sfx.wind(0);}
    this.cam.update(dt,this.veh,this.world);
    // 속도감 FOV
    const tgtFov=66+clamp(this.veh.speed-18,0,60)*.16;
    if(Math.abs(camera.fov-tgtFov)>.05){
      camera.fov+=(tgtFov-camera.fov)*Math.min(1,dt*3);camera.updateProjectionMatrix();}
    this.vis.sync(this.veh,this.shakeT);
    for(const a of this.ais)a.vis.sync(a.veh,0);
    if(this.shakeT>0)this.shakeT-=dt;
    updateHUD(dt);
  },
  consumeImpacts(v,vis,isPlayer){
    for(const imp of v.impacts){
      vis.applyImpact(imp,v);
      _vA.copy(imp.ln).applyQuaternion(v.body.quat);
      Fx.impactFx(imp.wp,_vA,imp.dv);
      if(isPlayer){
        this.cam.shake=Math.min(1,imp.dv/12);
        if(imp.dv>10&&Settings.autoSlowmo&&this.slowmoT<=0){this.slowmoT=1.2;bigMsg("💥",600);}
        if(this.mode==="crash"&&this.crash.phase==="run"&&imp.dv>3&&!this.crash.hitDone){
          this.crash.hitDone=true;this.crash.impactV=v.speed+imp.dv*.5;}}}
    v.impacts.length=0;},
  wheelFx(dt){
    const doFor=(v)=>{
      for(const w of v.wheels){
        if(!w.onGround)continue;
        if(w.skid>.3){
          const yaw=Math.atan2(2*(v.body.quat.w*v.body.quat.y+v.body.quat.x*v.body.quat.z),
            1-2*(v.body.quat.y*v.body.quat.y+v.body.quat.x*v.body.quat.x));
          const sid=SURF_IDS[w.surf];
          if(sid==="asphalt"||sid==="wet"||sid==="curb"){
            Fx.skidMark(w.cW.x,w.cW.y,w.cW.z,yaw);
            Fx.smokeAt(w.cW.x,w.cW.y+.1,w.cW.z,v.body.vel.x,v.body.vel.z,w.skid*.5);}
          else Fx.dustAt(w.cW.x,w.cW.y,w.cW.z,w.skid*.7);}
        else if((SURF_IDS[w.surf]==="sand"||SURF_IDS[w.surf]==="gravel")&&v.speed>8)
          Fx.dustAt(w.cW.x,w.cW.y,w.cW.z,.12);}};
    doFor(this.veh);for(const a of this.ais)doFor(a.veh);},

  resetCar(){
    const v=this.veh,sp=this.world.spawn;
    if((this.mode==="time"||this.mode==="race")&&this.world.checkpoints?.length){
      const T=this.mode==="time"?this.timing:this.race;
      const idx=(T.cp-1+this.world.checkpoints.length)%this.world.checkpoints.length;
      const c=this.world.checkpoints[idx],n=this.world.checkpoints[(idx+1)%this.world.checkpoints.length];
      v.reset(c.x,c.z,Math.atan2(n.x-c.x,n.z-c.z),true);}
    else if(this.mode==="crash")this.placeCrashCar();
    else v.reset(sp.x,sp.z,sp.yaw,true);
    toast("리셋");},
  repair(){this.veh.clearDamage();this.vis.repair();toast("🔧 수리 완료");Sfx.beep(760,.12,.12);},
  togglePause(force){
    if(this.state!=="play")return;
    this.paused=force!==undefined?force:!this.paused;
    $("pausePanel").classList.toggle("on",this.paused);
    if(this.paused){renderPauseMenu();Sfx.engine(0,0,false);Sfx.skid(0);Sfx.wind(0);}},
};
function setRecIfBetter(k,v,cmp){const cur=getRec(k);if(cur==null||cmp(v,cur))setRec(k,v);}

/* ---------- AI driver ---------- */
function stepAI(a,world,dt){
  const v=a.veh,wps=world.waypoints;
  if(!wps||!wps.length){v.throttle=0;v.brake=.5;return;}
  if(Game.mode==="race"&&Game.race&&!Game.race.started){v.throttle=0;v.brake=1;return;}
  const p=v.body.pos;
  let wp=wps[a.wp%wps.length];
  let dx=wp.x-p.x,dz=wp.z-p.z;
  if(dx*dx+dz*dz<144){a.wp=(a.wp+1)%wps.length;
    if(a.wp===0)a.lap++;
    wp=wps[a.wp%wps.length];}
  // race checkpoint progress
  if(Game.mode==="race"&&world.checkpoints){
    const cps=world.checkpoints,c=cps[a.cp%cps.length];
    const cdx=p.x-c.x,cdz=p.z-c.z;
    if(cdx*cdx+cdz*cdz<c.r*c.r*2.6){a.cp++;
      if(a.cp>=cps.length){a.cp=0;
        if(a.lap>Game.race.laps)a.finished=true;}}}
  // steering to lookahead
  const look=wps[(a.wp+1)%wps.length];
  const tx=lerp(wp.x,look.x,.45),tz=lerp(wp.z,look.z,.45);
  const yaw=Math.atan2(2*(v.body.quat.w*v.body.quat.y+v.body.quat.x*v.body.quat.z),
    1-2*(v.body.quat.y*v.body.quat.y+v.body.quat.x*v.body.quat.x));
  let ang=Math.atan2(tx-p.x,tz-p.z)-yaw;
  while(ang>Math.PI)ang-=Math.PI*2;while(ang<-Math.PI)ang+=Math.PI*2;
  v.steerIn=clamp(ang*1.6,-1,1);
  // speed
  const target=Math.min(wp.v,look.v+3)*a.rubber*(a.finished?.5:1);
  const sp=v.fwdSpeed();
  if(sp<target-1){v.throttle=clamp((target-sp)*.25,.25,1);v.brake=0;}
  else if(sp>target+2){v.throttle=0;v.brake=clamp((sp-target)*.14,.1,1);}
  else{v.throttle=.25;v.brake=0;}
  v.driveMode="D";v.handbrake=false;
  // stuck → reverse
  if(a.revT>0){a.revT-=dt;v.driveMode="R";v.throttle=.7;v.brake=0;v.steerIn=-v.steerIn;}
  else if(v.speed<.6){a.stuckT+=dt;if(a.stuckT>2.4){a.revT=1.3;a.stuckT=0;}}
  else a.stuckT=0;
  if(v.flipT>3)v.reset(wp.x,wp.z,Math.atan2(look.x-wp.x,look.z-wp.z),true);
}

/* ---------- HUD: arc gauge + minimap ---------- */
const GAUGE={ready:false};
function arcPath(cx,cy,r,a0,a1){
  const P=a=>[cx+r*Math.cos(a*DEG),cy+r*Math.sin(a*DEG)];
  const[x0,y0]=P(a0),[x1,y1]=P(a1);
  return"M "+x0+" "+y0+" A "+r+" "+r+" 0 "+(Math.abs(a1-a0)>180?1:0)+" 1 "+x1+" "+y1;}
function initGauge(){
  const d1=arcPath(80,66,54,160,380),d2=arcPath(80,66,41,160,380);
  for(const id of["gArcBg","gArcBg2","gArc"])$(id).setAttribute("d",d1);
  for(const id of["gArcRpmBg","gArcRpm"])$(id).setAttribute("d",d2);
  GAUGE.sL=$("gArc").getTotalLength();GAUGE.rL=$("gArcRpm").getTotalLength();
  for(const[id,L]of[["gArc",GAUGE.sL],["gArcRpm",GAUGE.rL]]){
    $(id).style.strokeDasharray=L;$(id).style.strokeDashoffset=L;}
  GAUGE.ready=true;}
function buildMinimap(){
  const w=Game.world,n=w.res+1;
  const c=document.createElement("canvas");c.width=n;c.height=n;
  const ctx=c.getContext("2d");
  const img=ctx.createImageData(n,n);
  for(let j=0;j<n;j++)for(let i=0;i<n;i++){
    const sf=SURF_IDS[w.sMap[j*n+i]];
    let r=0,g=0,b=0,a=0;
    if(sf==="asphalt"||sf==="lane"){r=172;g=182;b=198;a=235;}
    else if(sf==="curb"){r=214;g=92;b=80;a=235;}
    else if(sf==="walk"){r=120;g=128;b=140;a=160;}
    else if(sf==="ice"||sf==="wet"){r=110;g=170;b=205;a=120;}
    else a=0;
    const o=(j*n+i)*4;img.data[o]=r;img.data[o+1]=g;img.data[o+2]=b;img.data[o+3]=a;}
  ctx.putImageData(img,0,0);
  Game.mm={cnv:c,size:w.size};}
let _mmT=0;
function drawMinimap(dt){
  _mmT+=dt;if(_mmT<.12||!Game.mm)return;_mmT=0;
  const cv=$("minimap"),ctx=cv.getContext("2d"),S=cv.width;
  ctx.clearRect(0,0,S,S);
  ctx.drawImage(Game.mm.cnv,0,0,S,S);
  const toPx=(x,z)=>[(x/Game.mm.size+.5)*S,(z/Game.mm.size+.5)*S];
  // next checkpoint
  const T=Game.mode==="time"?Game.timing:Game.mode==="race"?Game.race:null;
  if(T&&Game.world.checkpoints?.length){
    const cp=Game.world.checkpoints[T.cp%Game.world.checkpoints.length];
    const[cx,cy]=toPx(cp.x,cp.z);
    ctx.strokeStyle="#3ddc84";ctx.lineWidth=4;
    ctx.beginPath();ctx.arc(cx,cy,7+Math.sin(performance.now()*.008)*2,0,7);ctx.stroke();}
  // AI dots
  ctx.fillStyle="#ff5252";
  for(const a of Game.ais){
    const[ax,ay]=toPx(a.veh.body.pos.x,a.veh.body.pos.z);
    ctx.beginPath();ctx.arc(ax,ay,5,0,7);ctx.fill();}
  // player arrow
  const b=Game.veh.body;
  const yaw=Math.atan2(2*(b.quat.w*b.quat.y+b.quat.x*b.quat.z),
    1-2*(b.quat.y*b.quat.y+b.quat.x*b.quat.x));
  const[px,py]=toPx(b.pos.x,b.pos.z);
  ctx.save();ctx.translate(px,py);ctx.rotate(-yaw);
  ctx.fillStyle="#ffb25e";ctx.strokeStyle="#0b0e13";ctx.lineWidth=2;
  ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(6,7);ctx.lineTo(-6,7);ctx.closePath();
  ctx.fill();ctx.stroke();ctx.restore();}
let _hudT=0;
function updateHUD(dt){
  const v=Game.veh;if(!v)return;
  _hudT+=dt;if(_hudT<.05)return;_hudT=0;
  const kmh=Math.abs(v.fwdSpeed())*3.6;
  $("speedVal").childNodes[0].nodeValue=String(kmh|0);
  $("gearVal").textContent=v.driveMode==="R"?"R":(v.speed<.3&&v.throttle===0?"N":v.gear);
  if(GAUGE.ready){
    $("gArc").style.strokeDashoffset=GAUGE.sL*(1-clamp(kmh/(v.spec.top+30),0,1));
    $("gArcRpm").style.strokeDashoffset=GAUGE.rL*(1-clamp(v.rpm/v.spec.engine.redline,0,1));}
  drawMinimap(.06);
  const dz=(el,val)=>{el.style.background=val>66?"var(--bad)":val>33?"var(--warn)":"var(--ok)";};
  dz($("dmgF"),v.dmg.f);dz($("dmgB"),v.dmg.b);dz($("dmgL"),v.dmg.l);dz($("dmgR"),v.dmg.r);
  updateModeWidget();
  if(Settings.debug){
    const w=v.wheels;
    $("debugHud").textContent=
      "FPS "+FPS.fps.toFixed(0)+"  phys "+Game.physMs.toFixed(1)+"ms\n"+
      "v "+(v.speed*3.6).toFixed(0)+"km/h  G "+v.peakG.toFixed(1)+"\n"+
      "slip FL "+(w[0].slipA/DEG).toFixed(0)+"° FR "+(w[1].slipA/DEG).toFixed(0)+"°\n"+
      "     RL "+(w[2].slipA/DEG).toFixed(0)+"° RR "+(w[3].slipA/DEG).toFixed(0)+"°\n"+
      "load "+w.map(x=>(x.load/1000).toFixed(1)).join(" ")+"\n"+
      "comp "+w.map(x=>(x.comp*100).toFixed(0)).join(" ")+"  surf "+SURF_IDS[w[0].surf];}
}
function updateModeWidget(){
  const el=$("modeWidget"),m=Game.mode;
  if(m==="time"&&Game.timing){
    const T=Game.timing;
    el.innerHTML='<div class="big">'+fmtTime(T.started?T.t:0)+'</div><div class="sub">베스트 '+fmtTime(T.best)+
      (T.sprint?"":" · CP "+T.cp+"/"+(Game.world.checkpoints?.length||0))+'</div>';}
  else if(m==="race"&&Game.race){
    const R=Game.race;
    el.innerHTML='<div class="big">'+R.rank+'<small>위</small> / '+(Game.ais.length+1)+'</div>'+
      '<div class="sub">LAP '+Math.min(R.lap,R.laps)+"/"+R.laps+'</div>';}
  else if(m==="drift"&&Game.drift){
    const D=Game.drift;
    el.innerHTML='<div class="big">'+((D.score+D.run)|0)+'</div><div class="sub">x'+D.combo.toFixed(1)+
      (D.wallBonus?" 🔥벽보너스":"")+' · 베스트 '+(D.best|0)+'</div>';}
  else if(m==="crash"){
    const c=Game.crash;
    el.innerHTML='<div class="big">'+(c.phase==="run"?(Game.veh.speed*3.6|0)+' km/h':'대기')+'</div>'+
      '<div class="sub">'+(c.phase==="run"?"주행 중…":"속도 설정 후 발사")+'</div>';}
  else{
    const s=SURF_IDS[Game.veh.wheels[0].surf]||"asphalt";
    const names={asphalt:"아스팔트",lane:"아스팔트",wet:"젖은 노면",gravel:"자갈",grass:"잔디",sand:"모래",ice:"빙판",snow:"눈",curb:"연석",walk:"보도"};
    el.innerHTML='<div class="big">자유주행</div><div class="sub">'+(names[s]||s)+' · '+Game.mapDef.name+'</div>';}
}
let _toastT=null;
function toast(msg,ms){
  const el=$("toast");el.textContent=msg;el.classList.add("on");
  clearTimeout(_toastT);_toastT=setTimeout(()=>el.classList.remove("on"),ms||1600);}
let _bigT=null;
function bigMsg(msg,ms,sub){
  const el=$("bigMsg");el.innerHTML=esc(String(msg))+(sub?"<small>"+esc(sub)+"</small>":"");
  el.classList.add("on");clearTimeout(_bigT);_bigT=setTimeout(()=>el.classList.remove("on"),ms||900);}

/* ---------- crash report ---------- */
function showCrashReport(){
  const c=Game.crash,v=Game.veh,vis=Game.vis;
  const parted=Object.keys(vis.detached).length;
  const vol=vis.defVol;
  const cost=Math.round(vol*900+parted*120+(v.dmg.f+v.dmg.b+v.dmg.l+v.dmg.r)*3);
  const grade=cost<80?"A":cost<300?"B":cost<800?"C":cost<1600?"D":"F";
  $("reportBox").innerHTML=
    '<h2>💥 크래시 리포트 <small>'+esc(Game.mapDef.name)+'</small></h2>'+
    '<div class="kv"><span>충돌 속도</span><b>'+(c.impactV*3.6).toFixed(1)+' km/h</b></div>'+
    '<div class="kv"><span>최대 감속</span><b>'+v.peakG.toFixed(1)+' G</b></div>'+
    '<div class="kv"><span>변형 부피 지수</span><b>'+vol.toFixed(1)+'</b></div>'+
    '<div class="kv"><span>분리된 파츠</span><b>'+parted+'개</b></div>'+
    '<div class="kv"><span>구역 손상</span><b>전 '+(v.dmg.f|0)+'% · 후 '+(v.dmg.b|0)+'% · 좌 '+(v.dmg.l|0)+'% · 우 '+(v.dmg.r|0)+'%</b></div>'+
    '<div class="kv"><span>수리비 환산</span><b>'+cost.toLocaleString()+'점 (등급 '+grade+')</b></div>'+
    '<div class="btnRow"><button class="btn" id="repAgain">🔁 다시 발사</button>'+
    '<button class="btn ghost" id="repFree">주변 살펴보기</button>'+
    '<button class="btn ghost" id="repExit">나가기</button></div>';
  $("reportPanel").classList.add("on");
  $("repAgain").onclick=()=>{$("reportPanel").classList.remove("on");Game.vis.repair();Game.veh.clearDamage();Game.launch();};
  $("repFree").onclick=()=>{$("reportPanel").classList.remove("on");Game.crash.phase="idle";Game.cam.mode="free";toast("프리 카메라 — 드래그로 감상");};
  $("repExit").onclick=()=>Game.exitToMenu();
}
function showResult(title,rows){
  $("resultBox").innerHTML='<h2>'+title+'</h2>'+
    rows.filter(r=>r[1]).map(r=>'<div class="kv"><span>'+r[0]+'</span><b>'+r[1]+'</b></div>').join("")+
    '<div class="btnRow"><button class="btn" id="resRetry">🔁 다시</button>'+
    '<button class="btn ghost" id="resExit">메뉴로</button></div>';
  $("resultPanel").classList.add("on");
  $("resRetry").onclick=()=>{$("resultPanel").classList.remove("on");Game.startGame();};
  $("resExit").onclick=()=>Game.exitToMenu();
}
function renderPauseMenu(){
  const box=$("pauseBtns");
  box.innerHTML='<button class="btn" id="pResume">▶ 계속하기</button>'+
    '<div class="seg" id="pAssist">'+["casual","sport","sim"].map(a=>
      '<button data-a="'+a+'" class="'+(Settings.assist===a?"sel":"")+'">'+
      ({casual:"캐주얼",sport:"스포츠",sim:"시뮬"})[a]+'</button>').join("")+'</div>'+
    '<button class="btn ghost" id="pRepair">🔧 수리 + 리셋</button>'+
    '<button class="btn ghost" id="pRestart">🔄 재시작</button>'+
    '<button class="btn danger" id="pExit">나가기</button>';
  $("pResume").onclick=()=>Game.togglePause(false);
  $("pRepair").onclick=()=>{Game.repair();Game.resetCar();Game.togglePause(false);};
  $("pRestart").onclick=()=>{$("pausePanel").classList.remove("on");Game.paused=false;Game.startGame();};
  $("pExit").onclick=()=>Game.exitToMenu();
  box.querySelectorAll("#pAssist button").forEach(b=>b.onclick=()=>{
    applyAssistPreset(b.dataset.a);Game.applyAssists(Game.veh);renderPauseMenu();toast("어시스트: "+b.textContent);});
}
/* ============================================================
   Input — multitouch (pointer-id tracked), keyboard, tilt,
   camera drag/pinch on canvas
   ============================================================ */
const Input=(()=>{
  const st={steer:0,gas:0,brake:0,hb:false};
  const keys={};
  let steerPtr=null,tiltVal=0;
  let whPtr=null,whAngle=0,whLast=0;      // steering wheel state (rad)
  const WH_MAX=2.4;                        // 잠금까지 ±137°
  const camPtrs=new Map();let pinchD=0;

  function hookBtn(el,on,off){
    el.addEventListener("pointerdown",e=>{e.preventDefault();el.setPointerCapture(e.pointerId);
      el.classList.add("press");Sfx.resume();on(e);});
    const end=e=>{el.classList.remove("press");off&&off(e);};
    el.addEventListener("pointerup",end);
    el.addEventListener("pointercancel",end);
    el.addEventListener("lostpointercapture",end);
  }
  function init(){
    // pedals
    hookBtn($("pedalGas"),()=>st.gas=1,()=>st.gas=0);
    hookBtn($("pedalBrake"),()=>st.brake=1,()=>st.brake=0);
    hookBtn($("btnHB"),()=>st.hb=true,()=>st.hb=false);
    hookBtn($("btnStL"),()=>st.steer=-1,()=>{if(st.steer<0)st.steer=0;});
    hookBtn($("btnStR"),()=>st.steer=1,()=>{if(st.steer>0)st.steer=0;});
    // steering slider
    const sz=$("steerZone");
    const updSteer=e=>{
      const r=sz.getBoundingClientRect();
      st.steer=clamp(((e.clientX-r.left)/r.width-.5)*2.4,-1,1);};
    sz.addEventListener("pointerdown",e=>{e.preventDefault();Sfx.resume();
      steerPtr=e.pointerId;sz.setPointerCapture(e.pointerId);updSteer(e);});
    sz.addEventListener("pointermove",e=>{if(e.pointerId===steerPtr)updSteer(e);});
    const sEnd=e=>{if(e.pointerId===steerPtr){steerPtr=null;st.steer=0;}};
    sz.addEventListener("pointerup",sEnd);sz.addEventListener("pointercancel",sEnd);
    // steering wheel
    const sw=$("steerWheel");
    const whAng=e=>{
      const r=sw.getBoundingClientRect();
      return Math.atan2(e.clientY-(r.top+r.height/2),e.clientX-(r.left+r.width/2));};
    sw.addEventListener("pointerdown",e=>{e.preventDefault();Sfx.resume();
      whPtr=e.pointerId;sw.setPointerCapture(e.pointerId);whLast=whAng(e);});
    sw.addEventListener("pointermove",e=>{
      if(e.pointerId!==whPtr)return;
      const a=whAng(e);let d=a-whLast;
      while(d>Math.PI)d-=Math.PI*2;while(d<-Math.PI)d+=Math.PI*2;
      whAngle=clamp(whAngle+d,-WH_MAX,WH_MAX);whLast=a;});
    const whEnd=e=>{if(e.pointerId===whPtr)whPtr=null;};
    sw.addEventListener("pointerup",whEnd);sw.addEventListener("pointercancel",whEnd);
    // camera gestures on canvas
    const gl=$("gl");
    gl.addEventListener("pointerdown",e=>{
      Sfx.resume();
      camPtrs.set(e.pointerId,{x:e.clientX,y:e.clientY});
      if(camPtrs.size===2){
        const a=[...camPtrs.values()];
        pinchD=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);}});
    gl.addEventListener("pointermove",e=>{
      const p=camPtrs.get(e.pointerId);if(!p)return;
      if(camPtrs.size===1&&Game.cam){
        Game.cam.onDrag(e.clientX-p.x,e.clientY-p.y);}
      p.x=e.clientX;p.y=e.clientY;
      if(camPtrs.size===2&&Game.cam){
        const a=[...camPtrs.values()];
        const d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);
        if(pinchD>0)Game.cam.onPinch(d/pinchD);
        pinchD=d;}});
    const camEnd=e=>{camPtrs.delete(e.pointerId);pinchD=0;};
    gl.addEventListener("pointerup",camEnd);gl.addEventListener("pointercancel",camEnd);
    // keyboard (desktop testing)
    addEventListener("keydown",e=>{keys[e.code]=true;
      if(e.code==="Space")e.preventDefault();
      if(e.code==="KeyP"||e.code==="Escape")Game.togglePause();
      if(e.code==="KeyR")Game.state==="play"&&!Game.paused&&Game.resetCar();
      if(e.code==="KeyC")Game.state==="play"&&toast("카메라: "+Game.cam.cycle());
      Sfx.resume();});
    addEventListener("keyup",e=>{keys[e.code]=false;});
    // tilt
    addEventListener("deviceorientation",e=>{
      if(e.gamma!=null){
        const landscape=Math.abs(window.orientation||0)===90||innerWidth>innerHeight;
        tiltVal=clamp((landscape?e.beta:e.gamma)/26,-1,1)*(window.orientation===-90?-1:1);}});
    applySteerModeUI();
  }
  function applySteerModeUI(){
    $("steerZone").style.display=Settings.steerMode==="slider"?"":"none";
    $("steerBtns").style.display=Settings.steerMode==="buttons"?"flex":"none";
    $("steerWheel").style.display=Settings.steerMode==="wheel"?"block":"none";
    $("ctlL").style.opacity=Settings.steerMode==="tilt"?"0":"1";
    $("ctlL").style.pointerEvents=Settings.steerMode==="tilt"?"none":"auto";
  }
  function requestTilt(){
    try{
      if(typeof DeviceOrientationEvent!=="undefined"&&DeviceOrientationEvent.requestPermission)
        DeviceOrientationEvent.requestPermission().catch(()=>{});
    }catch(e){}
  }
  function clear(){st.steer=0;st.gas=0;st.brake=0;st.hb=false;steerPtr=null;whPtr=null;whAngle=0;camPtrs.clear();
    for(const k in keys)keys[k]=false;
    document.querySelectorAll(".padBtn.press").forEach(b=>b.classList.remove("press"));}
  function read(){
    let steer=st.steer,gas=st.gas,brake=st.brake,hb=st.hb;
    if(Settings.steerMode==="tilt")steer=tiltVal;
    if(Settings.steerMode==="wheel")steer=clamp(whAngle/WH_MAX,-1,1);
    if(keys.ArrowLeft||keys.KeyA)steer=-1;
    if(keys.ArrowRight||keys.KeyD)steer=1;
    if(keys.ArrowUp||keys.KeyW)gas=1;
    if(keys.ArrowDown||keys.KeyS)brake=1;
    if(keys.Space)hb=true;
    return{steer:steer*Settings.sensitivity,gas,brake,hb};}
  // steering smoothing for knob/wheel visuals
  let knobV=0;
  function updateKnob(){
    const t=read().steer;
    knobV+=(clamp(t,-1,1)-knobV)*.3;
    const k=$("steerKnob");
    if(k&&Settings.steerMode==="slider")k.style.left=(50+knobV*32)+"%";
    if(Settings.steerMode==="wheel"){
      if(whPtr===null)whAngle*=.82;                  // 자동 복원
      $("steerWheelFace").style.transform="rotate("+(whAngle*57.3)+"deg)";}}
  function applyTo(v){
    const r=read();
    v.steerIn=-r.steer;   // 화면 오른쪽 입력 = 우회전 (조향 방향 반전)
    v.handbrake=r.hb;
    const fs=v.fwdSpeed();
    if(r.brake>0){
      if(fs>1||v.driveMode==="D"&&fs>-.2&&v.speed>1){v.brake=r.brake;v.throttle=r.gas;}
      else{v.driveMode="R";v.throttle=r.brake;v.brake=0;}}
    else{v.brake=0;v.throttle=r.gas;}
    if(r.gas>0&&v.driveMode==="R"&&fs>-1){v.driveMode="D";v.throttle=r.gas;v.brake=0;}
  }
  return{init,clear,read,applyTo,updateKnob,applySteerModeUI,requestTilt,state:st};
})();
/* ============================================================
   UI — menu flow: home → car → map → options → play
   ============================================================ */
const UI=(()=>{
  let view="home",pickMode="free",pickCar=0,pickColor=0,pickMap="proving";
  const body=()=>$("menuBody");

  function show(v){
    view=v;
    $("btnMenuBack").style.display=v==="home"?"none":"";
    $("menuCrumb").textContent={home:"",car:"차량 선택",map:"맵 선택",opts:"주행 설정",
      settings:"설정",editorList:"맵 에디터"}[v]||"";
    ({home,car,map,opts,settings,editorList})[v]();
    body().scrollTop=0;
  }
  function back(){
    const order={car:"home",map:"car",opts:"map",settings:"home",editorList:"home"};
    show(order[view]||"home");}

  /* ---------- home ---------- */
  function home(){
    const last=Store.get("lastPlay",null);
    body().innerHTML=
      '<div class="hero"><div class="heroBadge">REAL DRIVING SANDBOX</div>'+
      '<div class="heroTitle">부서지는 게<br><b>진짜다</b></div>'+
      '<p class="heroSub">서스펜션·타이어 풀 시뮬레이션 × 충돌 변형 — 박은 자리가 박은 만큼 찌그러진다</p>'+
      '<div class="btnRow" style="margin-top:16px"><button class="btn" id="quickPlay">▶ 바로 주행'+
      (last?' <small style="font-weight:500;opacity:.8">('+esc(CARS[last.carIdx]?.name||"")+')</small>':'')+'</button></div></div>'+
      '<div class="h1">게임 모드 <small>차량 6종 · 맵 7종 + 커스텀 에디터</small></div>'+
      '<div class="grid big">'+MODES.map(m=>
        '<button class="card mode" data-m="'+m.id+'"><span class="ic">'+m.icon+'</span>'+
        '<span class="nm">'+m.name+'</span><span class="ds">'+m.desc+'</span></button>').join("")+'</div>'+
      '<p class="note">실차 3D 모델(CC0 · Kenney Car Kit) · 물리는 어떤 어시스트에서도 항상 풀 시뮬레이션 · 변형은 수리 전까지 영구 누적</p>';
    $("quickPlay").onclick=()=>{
      Sfx.resume();Sfx.click();
      Game.mode="free";
      if(last){Game.opts.carIdx=clamp(last.carIdx||0,0,CARS.length-1);
        Game.opts.color=last.color||0;Game.opts.tod=last.tod||"day";
        Game.opts.mapId=last.mapId&&!last.mapId.startsWith("custom:")?last.mapId:"proving";}
      Game.startGame();};
    body().querySelectorAll(".card").forEach(c=>c.onclick=()=>{
      Sfx.resume();Sfx.click();
      pickMode=c.dataset.m;
      if(pickMode==="editor")show("editorList");
      else show("car");});
  }
  /* ---------- car ---------- */
  function car(){
    body().innerHTML='<div class="h1">'+MODES.find(m=>m.id===pickMode).name+' <small>차량을 고르세요</small></div>'+
      '<div class="grid big">'+CARS.map((c,i)=>
        '<button class="card'+(i===pickCar?" sel":"")+'" data-i="'+i+'">'+
        '<span class="tag">'+c.drive+' · '+c.hp+'hp</span>'+
        '<span class="ic">'+c.icon+'</span><span class="nm">'+c.name+'</span>'+
        '<span class="ds">'+c.desc+'</span>'+
        stat("속도",c.stats.spd)+stat("가속",c.stats.acc)+stat("그립",c.stats.grip)+
        '<span class="ds">0→100 '+c.acc+' · '+c.mass.toLocaleString()+'kg</span>'+
        '<div class="statRow" data-cols="'+i+'">'+c.colors.map((col,ci)=>
          '<i data-c="'+ci+'" style="display:inline-block;width:20px;height:20px;border-radius:50%;background:#'+col.toString(16).padStart(6,"0")+
          ';border:2px solid '+(ci===pickColor&&i===pickCar?"#fff":"transparent")+'"></i>').join("")+'</div>'+
        '</button>').join("")+'</div>'+
      '<div class="btnRow"><button class="btn" id="carNext">다음 →</button></div>';
    body().querySelectorAll(".card").forEach(c=>c.onclick=e=>{
      const ci=e.target.dataset?.c;
      pickCar=+c.dataset.i;
      if(ci!==undefined)pickColor=+ci;
      Sfx.click();car();});
    $("carNext").onclick=()=>{Sfx.click();show("map");};
  }
  function stat(nm,v){return '<div class="statRow"><em>'+nm+'</em><div class="bar"><i style="width:'+v+'%"></i></div></div>';}
  /* ---------- map ---------- */
  function map(){
    const avail=MAPS.filter(m=>m.modes.includes(pickMode));
    const customs=Store.keys("maps:").map(k=>Store.get(k,null)).filter(Boolean)
      .filter(d=>d.tiles.some(t=>t.t==="start"))
      .filter(d=>pickMode==="free"||(pickMode==="time"&&d.tiles.filter(t=>t.t==="check").length>1));
    if(!avail.find(m=>m.id===pickMap)&&!pickMap.startsWith("custom:"))pickMap=avail[0].id;
    body().innerHTML='<div class="h1">맵 선택</div><div class="grid big">'+
      avail.map(m=>{
        const rec=pickMode==="time"?getRec("time|"+m.id+"|"+CARS[pickCar].id):
                  pickMode==="drift"?getRec("drift|"+m.id):null;
        return '<button class="card'+(pickMap===m.id?" sel":"")+'" data-id="'+m.id+'">'+
        '<span class="ic">'+m.icon+'</span><span class="nm">'+m.name+'</span>'+
        '<span class="ds">'+m.desc+'</span>'+
        (rec?'<span class="recBadge">🏅 베스트 '+(pickMode==="drift"?(rec|0)+"점":fmtTime(rec))+'</span>':"")+
        '</button>';}).join("")+
      customs.map(d=>'<button class="card'+(pickMap==="custom:"+d.name?" sel":"")+'" data-id="custom:'+esc(d.name)+'">'+
        '<span class="ic">🛠️</span><span class="nm">'+esc(d.name)+'</span><span class="ds">커스텀 맵</span></button>').join("")+
      '</div><div class="btnRow"><button class="btn" id="mapNext">다음 →</button></div>';
    body().querySelectorAll(".card").forEach(c=>c.onclick=()=>{pickMap=c.dataset.id;Sfx.click();map();});
    $("mapNext").onclick=()=>{Sfx.click();show("opts");};
  }
  /* ---------- options ---------- */
  function opts(){
    const isRace=pickMode==="race";
    body().innerHTML='<div class="h1">주행 설정</div>'+
      seg("시간대","tod",[["day","낮"],["sunset","노을"],["night","밤"]],Game.opts.tod)+
      tglRow("손상 물리","damage","충돌 시 차체 변형·기능 손상"+(pickMode==="crash"?" (크래시 테스트는 항상 켜짐)":""),Game.opts.damage)+
      (isRace?seg("AI 수","aiCount",[["3","3대"],["4","4대"],["5","5대"]],String(Game.opts.aiCount))+
              seg("랩 수","laps",[["1","1랩"],["3","3랩"],["5","5랩"]],String(Game.opts.laps)):"")+
      seg("어시스트","assist",[["casual","캐주얼"],["sport","스포츠"],["sim","시뮬"]],Settings.assist)+
      '<p class="note">캐주얼: 속도감응 조향+자동 카운터스티어+TCS·ABS / 스포츠: ABS·TCS만 / 시뮬: 전부 OFF (물리는 어느 설정에서도 항상 풀 시뮬레이션)</p>'+
      '<div class="btnRow"><button class="btn" id="go" style="flex:1;font-size:18px">🏁 출발</button></div>';
    body().querySelectorAll("[data-seg]").forEach(b=>b.onclick=()=>{
      const k=b.dataset.seg,val=b.dataset.v;Sfx.click();
      if(k==="assist")applyAssistPreset(val);
      else if(k==="aiCount"||k==="laps")Game.opts[k]=+val;
      else Game.opts[k]=val;
      opts();});
    body().querySelectorAll("[data-tgl]").forEach(t=>t.onclick=()=>{
      Game.opts[t.dataset.tgl]=!Game.opts[t.dataset.tgl];Sfx.click();opts();});
    $("go").onclick=()=>{
      Game.mode=pickMode;
      Game.opts.carIdx=pickCar;Game.opts.color=pickColor;Game.opts.mapId=pickMap;
      Sfx.click();Game.startGame();};
  }
  function seg(label,key,items,cur){
    return '<div class="optRow"><div class="lb">'+label+'</div><div class="ct"><div class="seg">'+
      items.map(([v,n])=>'<button data-seg="'+key+'" data-v="'+v+'" class="'+(String(cur)===v?"sel":"")+'">'+n+'</button>').join("")+
      '</div></div></div>';}
  function tglRow(label,key,sub,on){
    return '<div class="optRow"><div class="lb">'+label+'<small>'+sub+'</small></div>'+
      '<div class="tgl'+(on?" on":"")+'" data-tgl="'+key+'"><i></i></div></div>';}

  /* ---------- settings ---------- */
  function settings(){
    const S=Settings;
    body().innerHTML='<div class="h1">설정</div>'+
      seg2("어시스트 프리셋","assist",[["casual","캐주얼"],["sport","스포츠"],["sim","시뮬"]],S.assist)+
      tgl2("ABS","absOn",S.absOn)+tgl2("TCS (트랙션 컨트롤)","tcsOn",S.tcsOn)+
      tgl2("자동 카운터스티어","ctrSteer",S.ctrSteer)+tgl2("저속 안정화","stab",S.stab)+
      seg2("조향 방식","steerMode",[["slider","슬라이더"],["wheel","휠"],["buttons","버튼"],["tilt","틸트"]],S.steerMode)+
      '<div class="optRow"><div class="lb">조향 감도 <small>'+S.sensitivity.toFixed(2)+'</small></div>'+
      '<div class="ct"><input type="range" id="sens" min="0.5" max="1.5" step="0.05" value="'+S.sensitivity+'"></div></div>'+
      tgl2("사운드","sound",S.sound)+
      '<div class="optRow"><div class="lb">볼륨</div><div class="ct"><input type="range" id="vol" min="0" max="1" step="0.05" value="'+S.volume+'"></div></div>'+
      tgl2("카메라 셰이크","camShake",S.camShake)+
      tgl2("그림자","shadows",S.shadows)+
      tgl2("자동 슬로모션 (강한 충돌 시)","autoSlowmo",S.autoSlowmo)+
      tgl2("디버그 오버레이 (FPS·슬립각·접지력)","debug",S.debug)+
      '<div class="btnRow"><button class="btn danger sm" id="wipe">저장 데이터 초기화</button></div>';
    body().querySelectorAll("[data-seg]").forEach(b=>b.onclick=()=>{
      const k=b.dataset.seg;Sfx.click();
      if(k==="assist")applyAssistPreset(b.dataset.v);
      else{S[k]=b.dataset.v;saveSettings();
        if(k==="steerMode"){Input.applySteerModeUI();if(b.dataset.v==="tilt")Input.requestTilt();}}
      settings();});
    body().querySelectorAll("[data-tgl]").forEach(t=>t.onclick=()=>{
      const k=t.dataset.tgl;S[k]=!S[k];
      if(["absOn","tcsOn","ctrSteer","stab"].includes(k))S.assist="custom";
      saveSettings();Sfx.setMaster();Sfx.click();
      if(k==="debug")$("debugHud").classList.toggle("on",S.debug);
      if(k==="shadows")applyShadows();
      settings();});
    $("sens").oninput=e=>{S.sensitivity=+e.target.value;saveSettings();};
    $("vol").oninput=e=>{S.volume=+e.target.value;saveSettings();Sfx.setMaster();};
    $("wipe").onclick=()=>{
      if(confirm("기록·설정·커스텀 맵을 모두 삭제할까요?")){
        for(const k of Store.keys(""))Store.del(k);
        location.reload();}};
    function seg2(l,k,items,cur){return seg(l,k,items,cur);}
    function tgl2(l,k,on){return '<div class="optRow"><div class="lb">'+l+'</div>'+
      '<div class="tgl'+(on?" on":"")+'" data-tgl="'+k+'"><i></i></div></div>';}
  }

  /* ---------- editor list ---------- */
  function editorList(){
    const maps=Store.keys("maps:").map(k=>Store.get(k,null)).filter(Boolean);
    body().innerHTML='<div class="h1">맵 에디터 <small>24×24 그리드 · 타일 20m</small></div>'+
      '<div class="grid big"><button class="card" id="edNew"><span class="ic">➕</span>'+
      '<span class="nm">새 맵 만들기</span><span class="ds">도로·커브·램프·벽·콘·체크포인트 배치</span></button>'+
      maps.map(d=>'<div class="card"><span class="ic">🗺️</span><span class="nm">'+esc(d.name)+'</span>'+
        '<span class="ds">타일 '+d.tiles.length+'개'+(d.tiles.some(t=>t.t==="start")?"":" · ⚠️ 출발점 없음")+'</span>'+
        '<div class="btnRow"><button class="btn sm" data-play="'+esc(d.name)+'">▶ 주행</button>'+
        '<button class="btn sm ghost" data-edit="'+esc(d.name)+'">✏️ 수정</button>'+
        '<button class="btn sm ghost" data-del="'+esc(d.name)+'">🗑</button></div></div>').join("")+'</div>';
    $("edNew").onclick=()=>{Sfx.click();Editor.open(null);};
    body().querySelectorAll("[data-play]").forEach(b=>b.onclick=()=>{
      const d=Store.get("maps:"+b.dataset.play,null);
      if(!d||!d.tiles.some(t=>t.t==="start")){toast("출발점이 없는 맵입니다");return;}
      Game.mode="free";Game.opts.carIdx=pickCar;Game.opts.mapId="custom:"+b.dataset.play;
      Game.startGame();});
    body().querySelectorAll("[data-edit]").forEach(b=>b.onclick=()=>Editor.open(b.dataset.edit));
    body().querySelectorAll("[data-del]").forEach(b=>b.onclick=()=>{
      if(confirm('"'+b.dataset.del+'" 맵을 삭제할까요?')){Store.del("maps:"+b.dataset.del);editorList();}});
  }
  function init(){
    $("btnMenuBack").onclick=()=>{Sfx.click();back();};
    $("btnSettings").onclick=()=>{Sfx.click();show(view==="settings"?"home":"settings");};
    show("home");
  }
  return{init,show};
})();
/* ============================================================
   Editor — 24×24 top-view tile grid
   ============================================================ */
const Editor=(()=>{
  const N=24;
  let tiles=[],name="",tool="road",rot=0,ordSeq=1,cv,ctx2,cell=20,ox=0,oy=0;
  function open(existing){
    if(existing){
      const d=Store.get("maps:"+existing,null);
      tiles=d?d.tiles.map(t=>({...t})):[];name=existing;
      ordSeq=Math.max(0,...tiles.map(t=>t.ord||0))+1;
    }else{tiles=[];name="";ordSeq=1;}
    rot=0;tool="road";
    $("edName").value=name;
    $("menu").classList.remove("on");$("editorScr").classList.add("on");
    buildPalette();resize();draw();
  }
  function close(){$("editorScr").classList.remove("on");$("menu").classList.add("on");UI.show("editorList");}
  function buildPalette(){
    $("edSide").innerHTML=ED_TILES.map(t=>
      '<button class="edTool'+(t.id===tool?" sel":"")+'" data-t="'+t.id+'">'+
      '<span class="sw" style="background:'+t.col+'"></span>'+t.name+'</button>').join("")+
      '<p class="note" style="padding:0 4px">탭=배치 · 회전 버튼으로 방향 전환 · 출발점 1개 필수</p>';
    $("edSide").querySelectorAll(".edTool").forEach(b=>b.onclick=()=>{tool=b.dataset.t;Sfx.click();buildPalette();});
  }
  function resize(){
    cv=$("edCanvas");
    const w=cv.clientWidth,h=cv.clientHeight;
    cv.width=w*devicePixelRatio;cv.height=h*devicePixelRatio;
    ctx2=cv.getContext("2d");ctx2.scale(devicePixelRatio,devicePixelRatio);
    cell=Math.floor(Math.min(w,h)/N);
    ox=(w-cell*N)/2;oy=(h-cell*N)/2;draw();
  }
  function draw(){
    if(!ctx2)return;
    const w=cv.clientWidth,h=cv.clientHeight;
    ctx2.clearRect(0,0,w,h);
    ctx2.fillStyle="#16331f";ctx2.fillRect(ox,oy,cell*N,cell*N);
    ctx2.strokeStyle="rgba(255,255,255,.07)";
    for(let i=0;i<=N;i++){
      ctx2.beginPath();ctx2.moveTo(ox+i*cell,oy);ctx2.lineTo(ox+i*cell,oy+N*cell);ctx2.stroke();
      ctx2.beginPath();ctx2.moveTo(ox,oy+i*cell);ctx2.lineTo(ox+N*cell,oy+i*cell);ctx2.stroke();}
    for(const t of tiles){
      const x=ox+t.x*cell,y=oy+t.z*cell,c=cell;
      const def=ED_TILES.find(d=>d.id===t.t);
      ctx2.save();ctx2.translate(x+c/2,y+c/2);ctx2.rotate(t.r*Math.PI/2);
      ctx2.fillStyle=def.col;
      if(t.t==="road"){ctx2.fillRect(-c*.3,-c/2,c*.6,c);}
      else if(t.t==="cross"){ctx2.fillRect(-c*.3,-c/2,c*.6,c);ctx2.fillRect(-c/2,-c*.3,c,c*.6);}
      else if(t.t==="curve"){
        ctx2.beginPath();ctx2.lineWidth=c*.6;ctx2.strokeStyle=def.col;
        ctx2.arc(c/2,-c/2,c/2,Math.PI/2,Math.PI);ctx2.stroke();}
      else if(t.t==="wall"){ctx2.fillRect(-c*.45,-c*.12,c*.9,c*.24);}
      else if(t.t==="bump"){ctx2.fillRect(-c*.4,-c*.08,c*.8,c*.16);
        ctx2.fillStyle="#23262c";
        for(let k=-1;k<=1;k+=2)ctx2.fillRect(k*c*.2-c*.05,-c*.08,c*.1,c*.16);}
      else if(t.t==="ramp"){ctx2.beginPath();ctx2.moveTo(-c*.35,-c*.35);ctx2.lineTo(c*.35,-c*.35);
        ctx2.lineTo(0,c*.4);ctx2.closePath();ctx2.fill();}
      else if(t.t==="cone"){ctx2.beginPath();ctx2.arc(0,0,c*.16,0,7);ctx2.fill();}
      else if(t.t==="check"){ctx2.globalAlpha=.7;ctx2.fillRect(-c*.4,-c*.4,c*.8,c*.8);
        ctx2.globalAlpha=1;ctx2.fillStyle="#0b0e13";ctx2.font="bold "+c*.4+"px sans-serif";
        ctx2.textAlign="center";ctx2.textBaseline="middle";ctx2.fillText(t.ord,0,0);}
      else if(t.t==="start"){ctx2.fillRect(-c*.4,-c*.4,c*.8,c*.8);
        ctx2.fillStyle="#0b0e13";ctx2.beginPath();ctx2.moveTo(0,-c*.25);
        ctx2.lineTo(c*.2,c*.15);ctx2.lineTo(-c*.2,c*.15);ctx2.closePath();ctx2.fill();}
      ctx2.restore();}
  }
  function place(gx,gz){
    if(gx<0||gz<0||gx>=N||gz>=N)return;
    const i=tiles.findIndex(t=>t.x===gx&&t.z===gz);
    if(tool==="erase"){if(i>=0)tiles.splice(i,1);draw();return;}
    if(i>=0)tiles.splice(i,1);
    const t={x:gx,z:gz,t:tool,r:rot};
    if(tool==="check")t.ord=ordSeq++;
    if(tool==="start")tiles=tiles.filter(x=>x.t!=="start"); // only one start
    tiles.push(t);draw();
  }
  function validate(){
    const starts=tiles.filter(t=>t.t==="start").length;
    if(!tiles.length)return"타일이 없습니다 — 도로부터 배치해 보세요";
    if(starts!==1)return"출발점(노란 타일)이 정확히 1개 필요합니다";
    return null;}
  function save(){
    name=($("edName").value||"").trim();
    if(!name){toast("맵 이름을 입력하세요");$("edName").focus();return false;}
    const err=validate();
    if(err){toast("⚠️ "+err,2400);return false;}
    Store.set("maps:"+name,{name,tiles,v:1});
    toast("💾 저장됨: "+name);return true;}
  function init(){
    $("edExit").onclick=()=>{Sfx.click();close();};
    $("edRotate").onclick=()=>{rot=(rot+1)%4;Sfx.click();toast("회전: "+rot*90+"°");};
    $("edSave").onclick=()=>{Sfx.click();save();};
    $("edTest").onclick=()=>{Sfx.click();
      if(!save())return;
      $("editorScr").classList.remove("on");
      Game.mode="free";Game.opts.mapId="custom:"+name;Game.startGame();};
    const pt=e=>{
      const r=cv.getBoundingClientRect();
      return[Math.floor((e.clientX-r.left-ox)/cell),Math.floor((e.clientY-r.top-oy)/cell)];};
    let painting=false;
    $("edCanvas").addEventListener("pointerdown",e=>{e.preventDefault();painting=true;
      $("edCanvas").setPointerCapture(e.pointerId);place(...pt(e));});
    $("edCanvas").addEventListener("pointermove",e=>{if(painting&&(tool==="road"||tool==="erase"||tool==="wall"))place(...pt(e));});
    $("edCanvas").addEventListener("pointerup",()=>painting=false);
    addEventListener("resize",()=>{if($("editorScr").classList.contains("on"))resize();});
  }
  return{open,init,resize};
})();
/* ============================================================
   Bootstrap — renderer, lights, time-of-day, main loop,
   auto-quality, stability guards
   ============================================================ */
let renderer,scene,camera,sunLight,hemiLight,headlight,skyDome,clouds;
const FPS={fps:60,ema:60,lowT:0,okT:0,tier:0};

function disposeGroup(g){
  g.traverse(o=>{
    if(o.geometry)o.geometry.dispose();
    if(o.material&&!o.material._shared){
      if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());
      else o.material.dispose();}});
}

const TOD={
  day:{horizon:0xaacdf0,zenith:0x2f6fd0,fog:0xa8c8e8,fogD:.0013,sun:0xfff4e0,sunI:1.5,
    hemi:0xcfe5ff,hemiG:0x4a5244,hemiI:.85,sunPos:[120,220,80],head:false,cloud:1},
  sunset:{horizon:0xffa25e,zenith:0x53306e,fog:0xe0916a,fogD:.0018,sun:0xffb066,sunI:1.3,
    hemi:0xffc9a0,hemiG:0x4a4038,hemiI:.7,sunPos:[220,60,-140],head:false,cloud:.9},
  night:{horizon:0x13203c,zenith:0x02040c,fog:0x0c1428,fogD:.0024,sun:0x8aa8e0,sunI:.4,
    hemi:0x36406a,hemiG:0x141820,hemiI:.65,sunPos:[-100,180,-60],head:true,cloud:.12},
};
function applyTimeOfDay(tod){
  const t=TOD[tod]||TOD.day;
  scene.background=null;
  scene.fog=new THREE.FogExp2(t.fog,t.fogD);
  sunLight.color.set(t.sun);sunLight.intensity=t.sunI;
  sunLight.position.set(...t.sunPos);
  hemiLight.color.set(t.hemi);hemiLight.groundColor.set(t.hemiG);hemiLight.intensity=t.hemiI;
  if(headlight)headlight.visible=t.head;
  // sky dome gradient
  const g=skyDome.geometry,pos=g.attributes.position;
  if(!g.attributes.color)g.setAttribute("color",new THREE.BufferAttribute(new Float32Array(pos.count*3),3));
  const col=g.attributes.color,hz2=new THREE.Color(t.horizon),zn=new THREE.Color(t.zenith),tmp=new THREE.Color();
  for(let i=0;i<pos.count;i++){
    const f=Math.pow(clamp(pos.getY(i)/1500,0,1),.55);
    tmp.copy(hz2).lerp(zn,f);
    col.setXYZ(i,tmp.r,tmp.g,tmp.b);}
  col.needsUpdate=true;
  if(clouds)clouds.material.opacity=.85*t.cloud;
}
function applyShadows(){
  const on=Settings.shadows&&FPS.tier<1;
  renderer.shadowMap.enabled=on;
  sunLight.castShadow=on;
  scene.traverse(o=>{if(o.material)o.material.needsUpdate=true;});
}

function initRenderer(){
  try{
    renderer=new THREE.WebGLRenderer({canvas:$("gl"),antialias:true,powerPreference:"high-performance"});
  }catch(err){
    $("loadTip").textContent="⚠️ WebGL을 사용할 수 없습니다 — 브라우저/기기 설정을 확인해 주세요";
    throw err;}
  renderer.setPixelRatio(Math.min(devicePixelRatio,2));
  renderer.setSize(innerWidth,innerHeight);
  renderer.shadowMap.type=THREE.PCFShadowMap;
  renderer.toneMapping=THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure=1.05;
  scene=new THREE.Scene();
  camera=new THREE.PerspectiveCamera(66,innerWidth/innerHeight,.1,2200);
  // sky dome + clouds
  skyDome=new THREE.Mesh(new THREE.SphereGeometry(1500,24,12),
    new THREE.MeshBasicMaterial({vertexColors:true,side:THREE.BackSide,fog:false}));
  skyDome.frustumCulled=false;
  scene.add(skyDome);
  const cl=[];let cseed=5;const crnd=()=>{cseed=(cseed*16807)%2147483647;return cseed/2147483647;};
  for(let k=0;k<14;k++)cl.push({geo:new THREE.SphereGeometry(1,7,5),color:0xeef2f7,
    x:(crnd()-.5)*2400,y:150+crnd()*120,z:(crnd()-.5)*2400,
    sx:60+crnd()*90,sy:10+crnd()*10,sz:40+crnd()*70});
  clouds=new THREE.Mesh(mergeGeoms(cl),new THREE.MeshBasicMaterial({vertexColors:true,fog:false,transparent:true,opacity:.85}));
  scene.add(clouds);
  sunLight=new THREE.DirectionalLight(0xffffff,1);
  sunLight.shadow.mapSize.set(1024,1024);
  const sc=90;
  sunLight.shadow.camera.left=-sc;sunLight.shadow.camera.right=sc;
  sunLight.shadow.camera.top=sc;sunLight.shadow.camera.bottom=-sc;
  sunLight.shadow.camera.far=700;sunLight.shadow.bias=-.0004;
  scene.add(sunLight);scene.add(sunLight.target);
  hemiLight=new THREE.HemisphereLight(0xcfe5ff,0x51584a,.75);
  scene.add(hemiLight);
  headlight=new THREE.SpotLight(0xfff2cc,2.2,80,.5,.45,1);
  headlight.visible=false;
  scene.add(headlight);scene.add(headlight.target);
  Fx.init(scene);
  Game.cam=new GameCamera(camera);
  applyShadows();
  addEventListener("resize",()=>{
    camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();
    renderer.setSize(innerWidth,innerHeight);});
}

/* auto quality (안정성 6) */
function autoQuality(dt){
  FPS.ema=lerp(FPS.ema,1/Math.max(dt,1e-3),.05);FPS.fps=FPS.ema;
  if(Settings.quality!=="auto"||Game.state!=="play")return;
  if(FPS.ema<45){FPS.lowT+=dt;FPS.okT=0;}
  else{FPS.okT+=dt;FPS.lowT=0;}
  if(FPS.lowT>3&&FPS.tier<3){
    FPS.tier++;FPS.lowT=0;
    if(FPS.tier===1)applyShadows();
    if(FPS.tier===2)Fx.setQuality(.5);
    if(FPS.tier===3)renderer.setPixelRatio(Math.min(devicePixelRatio,2)*.85);}
}

/* main loop */
let _last=performance.now();
function mainLoop(t){
  requestAnimationFrame(mainLoop);
  let dt=(t-_last)/1000;_last=t;
  if(dt>.05)dt=.05;           // frame clamp (안정성 1)
  autoQuality(dt);
  try{
    if(Game.state==="play"){
      Game.frame(dt);
      Input.updateKnob();
      // headlight follows player
      if(headlight&&headlight.visible&&Game.veh){
        const b=Game.veh.body;
        _t6.set(0,0,Game.veh.spec.body.hz);b.localToWorld(_t6,headlight.position);
        _t7.set(0,-1.5,30);b.localToWorld(_t7,headlight.target.position);}
      skyDome.position.set(camera.position.x,0,camera.position.z);
      sunLight.target.position.copy(Game.veh.body.pos);
      sunLight.position.set(Game.veh.body.pos.x+TOD[Game.opts.tod].sunPos[0]*.5,
        Game.veh.body.pos.y+TOD[Game.opts.tod].sunPos[1]*.5,
        Game.veh.body.pos.z+TOD[Game.opts.tod].sunPos[2]*.5);
      renderer.render(scene,camera);
    }else if(Game.state==="menu"&&Game.world){
      // idle orbit behind menu
      renderer.render(scene,camera);}
  }catch(err){
    console.error(err);
    if(!mainLoop._err){mainLoop._err=true;toast("⚠️ 오류 복구 중…");
      try{Game.veh&&Game.resetCar();}catch(e2){}
      setTimeout(()=>mainLoop._err=false,2000);}}
}

/* buttons */
function initHudButtons(){
  $("btnPause").onclick=()=>{Sfx.click();Game.togglePause();};
  $("btnReset").onclick=()=>{Sfx.click();Game.resetCar();};
  $("btnCam").onclick=()=>{Sfx.click();toast("카메라: "+Game.cam.cycle());};
  $("btnSlow").onclick=()=>{Sfx.click();Game.manualSlow=!Game.manualSlow;
    $("btnSlow").classList.toggle("on",Game.manualSlow);
    toast(Game.manualSlow?"슬로모션 ON":"슬로모션 OFF");};
  $("btnRepair").onclick=()=>{Sfx.click();Game.repair();};
  $("btnLaunch").onclick=()=>{Sfx.click();Game.crash.vTarget=+$("crashSpeed").value;Game.launch();};
  $("crashSpeed").oninput=e=>{
    $("crashSpeedVal").textContent=e.target.value+" km/h";
    Game.crash.vTarget=+e.target.value;};
  // crash target select
  const seg=$("crashTargetSeg");
  seg.innerHTML='<button class="sel">콘크리트 벽</button><button>배리어</button>';
  seg.children[0].onclick=()=>{Game.crash.target=0;seg.children[0].classList.add("sel");
    seg.children[1].classList.remove("sel");Game.placeCrashCar();};
  seg.children[1].onclick=()=>{Game.crash.target=1;seg.children[1].classList.add("sel");
    seg.children[0].classList.remove("sel");Game.placeCrashCar();};
  $("ctlHint").textContent="";
}

/* visibility → pause (안정성 5) */
document.addEventListener("visibilitychange",()=>{
  if(document.hidden){Input.clear();if(Game.state==="play")Game.togglePause(true);}});
addEventListener("blur",()=>Input.clear());

/* global error net (안정성) — 로딩 중이면 화면에 원인 표시 */
addEventListener("error",e=>{
  console.warn("caught:",e.message);
  try{
    const ld=$("loading");
    if(ld&&!ld.classList.contains("off"))
      $("loadTip").textContent="⚠️ "+(e.message||"오류")+(e.lineno?" (line "+e.lineno+")":"");
  }catch(_){}});
addEventListener("unhandledrejection",e=>{console.warn("caught rejection");e.preventDefault();});

/* boot */
function boot(){
  const steps=[
    ["차량 모델 로드…",()=>{for(const c of CARS)if(!c.modelScale)applyModelSpec(c);}],
    ["렌더러 초기화…",()=>initRenderer()],
    ["입력 시스템…",()=>{Input.init();initHudButtons();initGauge();}],
    ["에디터 준비…",()=>Editor.init()],
    ["메뉴 구성…",()=>{UI.init();$("debugHud").classList.toggle("on",Settings.debug);}],
    ["완료!",()=>{
      $("loading").classList.add("off");$("loading").classList.remove("on");
      requestAnimationFrame(mainLoop);}]];
  let i=0;
  const run=()=>{
    if(i>=steps.length)return;
    const[msg,fn]=steps[i];
    $("loadTip").textContent=msg;
    $("loadBar").firstElementChild.style.width=((i+1)/steps.length*100)+"%";
    try{fn();}catch(e){console.error(e);$("loadTip").textContent="⚠️ "+e.message;}
    i++;setTimeout(run,60);};
  run();
}
/* 디버깅·테스트용 전역 노출 (미니파이 IIFE 대비) */
